programs.haiku:
"""Layer-0 MLP down_proj component 4801: a weak, mostly token-level direction.

Its activation is small noise (std about 0.035) with no clear concept behind it.
This program only captures the few lexical tendencies that are visible on average:

* "For" / "for" / "unto" (a sentence-initial or purpose "for") push it up.
* Prepositions and articles ("of", "to", "in", "on", "with", "at", "from", "the", "a")
  lean slightly positive.
* Code and bracket punctuation, "and", "is", "not", "you" lean slightly negative.

Every other token predicts the baseline, a small negative constant.
"""

READS = ()

FOR_WORDS = {" For", "For", "for", " unto"}
PREPOSITIONS = {" of", " to", " in", " on", " with", " at", " from", " as", " by", " into",
                " the", " a", " The"}
NEGATIVE = {" and", " (", ")", " =", " is", "   ", " not", " you", " or", "  ", "\n\n", ":"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in FOR_WORDS:
        value = 0.07
    elif token in PREPOSITIONS:
        value = 0.004
    elif token in NEGATIVE:
        value = -0.004
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate a Python-source syntax response, not a general English-word response.

Python statements, assignments, object references and iteration/introspection
calls get negative values. Dictionary braces and return-type arrows get positive
values. Statements beginning a line are stronger than inline mentions; numbered
listings and JSON-escaped source are weaker. Recent text resets per document.
Document-initial syntax has separate calibrated values. The rules intentionally
omit many smaller lexical responses.
"""
import re

READS = ()
PYTHON = re.compile(
    r'\bdef\s+\w+\s*\(|\bfrom\s+[\w.]+\s+import\b|'
    r'(?m:^\s*import\s+(?!java\b|javax\b|org\b|com\b|cn\b|net\b)'
    r'[\w.]+(?:\s+as\s+\w+)?\s*$)|'
    r'\b(?:self|cls|np|pd|plt)\.|\b__\w+__\b|\bas (?:np|pd)\b|'
    r'\.strip\(|\.add_argument\(|\.parse_args\(|\b(?:True|False|None)\b|'
    r'```python|/env python|\.py\b|' + '"""' + "|'''|" +
    r'\b(?:len|range|enumerate|isinstance|print|hasattr|getattr|setattr)\(|'
    r'(?m:^\s*(?:if|for|elif|else|try|except|while)\b[^;{}\n]{0,100}:\s*$)|'
    r'(?m:^\s*with\b[^;{}\n]{0,100}\bas\s+\w+:\s*$)'
)
OTHER_CODE = re.compile(
    r'\b(?:public|private)\s+(?:static\s+)?(?:class|void|int|String)\b|'
    r'\b(?:const|let|var)\s+(?:mut\s+)?\w+\s*(?:=|:)|'
    r'\bfunction\s+\w*\s*\(|\bfn\s+\w+\s*\(|\bimpl\s+|'
    r'\bpackage\s+[\w.]+|\bfunc\s+|:=|\busing\s+[\w.]+;|'
    r'#include|\)\s*\{|```(?:js|ts|java|cpp|csharp|rust)|'
    r'\bimport\s+(?:java|javax|org|com|cn|net)\.|'
    r"\bimport[^\n]*\bfrom\s+['\"]|(?m:^\s*module\s+\w+)"
)
# Each family has a line-start response and an inline response.
KEYWORDS = {}
for words, line_value, inline_value in (
    (('def', 'class'), -3.1, -0.4),
    (('from',), -3.3, -0.2),
    (('import',), -3.25, -2.25),
    (('print',), -2.1, -0.8),
    (('assert', 'except'), -2.65, -0.7),
    (('elif',), -2.6, -2.2),
    (('if', 'for', 'else', 'while'), -1.8, -0.25),
    (('return', 'raise'), -2.05, -0.5),
    (('try', 'break', 'pass', 'continue'), -1.7, 0.0),
    (('yield', 'with'), -1.4, -0.2),
):
    KEYWORDS.update(dict.fromkeys(words, (line_value, inline_value)))
INITIAL = {'from': -4.6, 'import': -3.35, 'def': -3.27,
           'class': -2.91, 'print': -2.17, '#': -1.5, ' =': -1.18}
ITERATION = {'range', 'enumerate'}
INTROSPECTION = {'isinstance', 'getattr', 'hasattr', 'setattr'}


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        recent, line, n = '', '', 0
    else:
        recent, line, n = carry[1:]
    word = s.strip()
    listing = line.strip().isdigit()
    if listing and word.startswith(':'):
        word = word[1:]
    start = listing or bool(re.fullmatch(r'\s*(?:#\s*|async\s*|[+-]\s*)?', line))
    start = start or bool(re.search(r'[\'\"]:\s*[\'\"]\s*$', line))
    context = recent.replace('\\n', '\n')
    relevant = (word in KEYWORDS or word in ITERATION | INTROSPECTION
                or word in {'in', 'self', 'plt', 'lambda', '{', '->', '::'}
                or word.startswith(('#', '=', '+', '-', '.', '@')) or s.isspace())
    other = relevant and bool(OTHER_CODE.search(context))
    py = relevant and bool(PYTHON.search(context)) and not other
    if start and word in {'def', 'elif', 'print', 'except', 'assert'} and not other:
        py = True
    escaped = recent.rfind('\\n') > recent.rfind('\n')
    if escaped:
        scale = 0.58 if not s[:1].isspace() else 0.75
    else:
        scale = 0.75 if listing else 1.0
    value = -0.003
    if word in KEYWORDS:
        if py:
            value = KEYWORDS[word][0 if start else 1] * scale
            if word == 'print' and start and not s[:1].isspace():
                value *= 0.8
            if word == 'from' and start and s.startswith(' '):
                value = -2.1 * scale
        elif word == 'import':
            if s.startswith(' '):
                value = -0.65 * scale
            else:
                value = -0.85 * scale if start and not other else 0.0
        elif word == 'from':
            value = -0.85 * scale if start and not other else 0.04
        elif word == 'def':
            value = -0.25
        elif start and not other:
            value = -0.3 if word in {'if', 'for', 'return'} else 0.0
    elif s == ' =':
        variable = bool(re.fullmatch(r'\s*[A-Za-z_]\w*', line))
        if py:
            value = (-1.3 if variable else -0.65) * scale
        else:
            value = -0.45 * scale if variable and not other else -0.04
    elif word in {'+=', '-='}:
        value = -0.9 * scale if py else -0.04
    elif (word.startswith('=')
          and word[1:] in {'True', 'False', 'None', 'self', 'lambda'}):
        value = -0.7 * scale
    elif word == 'self' and s[:1].isspace() and py:
        value = (-1.65 if start else -0.75) * scale
    elif word == '(self':
        value = -0.36
    elif word == 'plt':
        value = (-1.8 if s.startswith(' ') else -1.3) * scale
    elif (s.startswith(' ') and py
          and word in ITERATION | INTROSPECTION | {'in', 'lambda'}):
        magnitude = -0.2 if word == 'in' else -0.8 if word == 'lambda' else -0.5
        value = magnitude * scale
    elif word in {'.append', '.extend'} or word.startswith('.assert'):
        value = -0.9 * scale if not other else 0.0
    elif word.startswith('@') and start and py:
        value = -1.3 * scale
    elif word == '{' and s.startswith(' '):
        magnitude = 1.25 if recent.rstrip().endswith('=') else 0.6
        value = magnitude * scale if py else 0.04
    elif word == '->':
        value = 0.5 * scale if py else -0.03
    elif word == '::':
        value = 0.8 if '.py' in context else 0.05
    elif word.startswith('#'):
        value = -0.7 * scale if py else (-0.22 if start else 0.0)
        if word[1:] in {'from', 'def', 'import'}:
            value = -4.7 if n == 0 else -3.5 * scale
    elif s.isspace() and '\n' not in s and py:
        value = -min(0.4, 0.025 * len(s)) * scale
    if n == 0:
        value = INITIAL.get(s, value)
    recent = (recent + s)[-900:]
    line = (line + s).replace('\\n', '\n').rsplit('\n', 1)[-1][-250:]
    return (doc, recent, line, n + 1), float(value)

programs.luna:
"""Give small signed pulses to a few code words and delimiters."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token in {'def', 'elif'}:
        return None, -0.55
    if token in {'assert', 'print', 'import'}:
        return None, -0.45
    if token == '=':
        return None, -0.35
    if token == '::':
        return None, 0.4
    return None, 0.0

programs.sol:
"""Approximate a short ra/la-like spelling feature, not a semantic topic.

Strong positives recognize isolated ra and related spellings across scripts.
Length, nearby letters, capitalization, whitespace and accents modulate the
Latin response; selected ra-bearing word stems receive moderate responses.
An additional mostly negative feature recognizes 'also' and translations.
English 'also' uses the preceding word, but never crosses a document boundary.
This captures the dominant patterns, not all token-specific/context effects.
"""
import unicodedata

READS = ()
RA_GLYPHS = {
    'ら': 3.1, 'ラ': 2.65, '拉': 2.6, 'ра': 2.0,
    'را': 1.8, '라': 1.8, '래': 1.4, 'レ': 0.6,
}
ALSO_TRANSLATIONS = frozenset((
    'anche', 'auch', 'aussi', 'également', 'también',
    'также', 'również', 'także', 'また',
))


def response(token, previous=''):
    word = token.strip()
    t = word.lower().strip('-_/.(')
    spaced = token[:1].isspace()
    if t == 'also':
        if word[:1].isupper():
            return -1.0
        if previous in ('can', 'may', 'could', 'might', 'but'):
            return -0.55
        if previous == 'see':
            return -0.8
        if previous in ('was', 'were'):
            return 0.17
        if previous in ('is', 'are'):
            return -0.07
        return -0.17
    if t in ALSO_TRANSLATIONS:
        return -0.95 if t in ('anche', 'また', 'także') else -0.45
    if t in RA_GLYPHS:
        return RA_GLYPHS[t]
    if t.endswith('ラ') and len(t) == 2:
        return 2.6 if t[0] in 'トドブフ' else 1.2
    if t.endswith('たら'):
        return 1.0 if len(t) <= 4 else 0.4
    if 'ら' in t or 'ラ' in t:
        return 0.15
    if '拉' in t:
        return 1.8 if t.endswith('拉') else 0.3
    if 'ра' in t:
        if t.endswith('ра'):
            if len(t) > 4:
                return 0.3
            return 0.6 if t[-3] in 'аеёиоуыэюя' else 1.4
        return 0.8 if len(t) == 3 and t[-1] != 'з' else 0.1
    normalized = unicodedata.normalize('NFD', t)
    accented_a = any(unicodedata.combining(c) and normalized[i - 1] == 'a'
                     for i, c in enumerate(normalized) if i)
    t = ''.join(c for c in normalized if not unicodedata.combining(c))
    scale = 0.5 if accented_a else 1.0
    if 'ra' not in t:
        return 0.3 if t in ('la', 'ла') and not spaced else 0.0
    if t == 'ra':
        value = (2.7 if spaced else 3.65 if word.isupper() else
                 2.3 if word[:1].isupper() else 3.95)
    elif t.endswith('ra'):
        onset = t[:-2]
        n = len(onset)
        if onset[-1] in 'aeiou':
            value = (1.2 if onset[-1] in 'au' else 2.0) * 0.35 ** (n - 1)
            value *= 0.8 if spaced else 1.0
        else:
            value = (2.45, 2.1, 1.3, 0.6, 0.1)[min(n - 1, 4)]
            if n == 1 and onset in 'bfhk':
                value = 3.1
            if n == 2 and onset.endswith('r'):
                value = 0.9
            if n == 3 and onset.endswith('nd'):
                value = 2.2
            if t == 'extra':
                value = 0.1
        if accented_a and n == 1:
            scale = 0.2
    elif t.startswith('ra') and len(t) == 3:
        value = (1.8 if t[-1] == 's' else 1.4 if t[-1] in 'hf' else
                 1.0 if t[-1] in 'iz' else 0.45)
    elif t.endswith('ras') and len(t) == 4:
        value = 0.8
    elif t.startswith(('draft', 'graft')) or t == 'raft':
        value = 1.1
    elif t.startswith(('fract', 'raction', 'traff', 'traj')):
        value = 0.8
    elif t.startswith('trauma'):
        value = 1.6
    elif t == 'infrastructure':
        value = 1.0
    else:
        value = 0.1 if len(t) <= 6 else 0.0
    return value * scale


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().lower()
    return None, float(response(prefix.token_strings[-1], previous))

programs.haiku:
"""Component layers.0.mlp.down_proj:4806 -- a "ra syllable" detector.

What it does: it switches on for word pieces that spell or sound like the syllable
"ra" *as a fragment of a longer word*: "ra", "RA", "stra", "ora", "era", "tra", "bra",
" Fra", " infra", and the same sound in other scripts (kana ら / ラ, Korean 라, Chinese 拉,
Cyrillic ра). It is strongest on the bare "ra" piece and weaker on other fragments.
Whole ordinary words that happen to end in "ra" (para, cara, hora, otra) stay off, and
full words that merely contain "ra" (range, array, program, rate) stay near zero.
Capitalised "Also" and its translations (anche, auch) push it slightly negative.

It is a token-level rule: the activation depends on the current token only, so the
program ignores the carry and the context.
"""

# Whole words that end in "ra" but are not word fragments: they stay off.
WHOLE_RA_WORDS = {"para", "cara", "hora", "otra", "sera", "vara", "tera", "tara", "cura"}
# The "ra" sound in other scripts: hiragana ら, katakana ラ, hangul 라, hanzi 拉, Cyrillic ра.
RA_SOUND_TOKENS = {"ら", "ラ", "라", "拉", "래", "ра"}
# "also" in other languages, and English "Also" (a mild negative).
ALSO_WORDS = {"Also", "anche", "auch", "juga", "także"}

READS = ()


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    word = piece.strip().lower()
    if piece.strip() in RA_SOUND_TOKENS:
        value = 2.5
    elif word in WHOLE_RA_WORDS:
        value = 0.0
    elif word == "ra":
        value = 4.0
    elif word.endswith("ra") and len(word) <= 4:
        value = 2.5  # stra, ora, era, tra, bra, ara, ...
    elif word.startswith("ra") and len(word) <= 4:
        value = 0.5  # ras, rag, rai, ran, raf
    elif piece.strip() in ALSO_WORDS:
        value = -0.8
    else:
        value = 0.0
    return None, value

programs.sol:
"""Recognize short, delimiter-bound templates in text and source code.

A nonbreaking-space comment signature, a shell filter, a type-union option,
page-title source labels, and code/documentation boilerplate get negative
responses. A few ordinary boilerplate phrases get positive responses.
An all-middle-dot document prefix gets a negative response.
Unrecognized text stays close to zero. The line buffer is bounded and is
reset, together with the previous token, at document boundaries.

This is a partial approximation of the conspicuous training responses, not
a model of the many weaker, token-specific background activations.
"""
READS = ()

TITLE_SOURCES = {'YouTube', 'Wikipedia', 'Wikimedia', 'TripAdvisor', 'Reddit'}
MEDIA_LABELS = {'Duration', 'PDF', 'PowerPoint'}
EMPTY_TYPES = {'null', 'undefined'}
PIPE_FILTERS = {'cut', 'wc', 'awk', 'sort', 'uniq', 'sed', 'head', 'tail'}


def response(token, previous, line, dots_only):
    """Estimate the response to the current token in its local text context."""
    word, before = token.strip(), previous.strip()
    if token == '\u00a0':
        if previous == ' –':
            return -2.06
        if previous == '–':
            return -0.93
        return -0.052
    if word == 'git' and token == 'git':
        if before == '--':
            return -1.46
        if before == '.' and ' -- ' in line:
            return -0.90
        return -0.12
    if word == 'grep':
        if before == '|':
            return -0.99
        if before == '--':
            return -0.64
        if previous == 'args':
            return -0.44
        return -0.065
    if before == '|':
        if word in EMPTY_TYPES:
            return -1.20
        if word == 'None':
            return -0.43
        if word in PIPE_FILTERS:
            if word in {'cut', 'wc'}:
                return -0.56
            if word in {'head', 'tail'}:
                return -0.15
            return -0.33
        if word.isalpha() and token.startswith(' '):
            return -0.06
        return -0.026
    if before == '-' and word in TITLE_SOURCES | MEDIA_LABELS:
        return -1.60
    if word == 'webkit' and before == '-':
        return -1.25
    if before == '--' and word in {'Docs', 'Dump', 'Table', 'Records'}:
        return -0.75
    if token == '-doc' and previous == '-user':
        return -0.80
    if token == '_INCREMENT' and before == 'AUTO' and '--' in line:
        return -1.05
    if token == ' `' and before.lower() == 'table' and '--' in line:
        return -0.49
    if word == 'permalink' and before == '[#':
        return -0.56
    if word == 'Continue' and ('…' in previous or '...' in previous):
        return -0.77 if before != '[…]' else -0.23
    if word.lower() in {'reading', 'more'} and before in {'Continue', 'Read'}:
        return -0.22
    if token == ' (@' and '—' in line:
        return -1.35
    if word == 'Logged' and before == 'IP':
        return -1.70
    if word == 'born' and before == '(':
        return -0.27
    if token == '··' and dots_only:
        return -0.28
    if token.startswith('.') and ('import ' in line or 'using ' in line):
        if word.endswith('Exception'):
            return -0.48
        if word == '.Nullable':
            return -0.94
        if before == '.Threading' and word == '.Tasks':
            return -0.94
        if before == '.os' and word == '.Bundle':
            return -0.68
        if len(token) > 1 and token[1].isupper():
            return -0.062
    if word in {'.createElement', '.createTextNode'} and 'doc' in previous.lower():
        return -0.52
    if word == 'by' and before in {'Posted', 'Submitted'}:
        return 0.39
    if word == 'under' and before in {'Licensed', 'icensed'}:
        return 0.43
    if word == 'words' and before == 'other':
        return 0.37
    if word == 'frac' and before == '\\':
        return -0.08
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line, dots_only = '', '', True
    else:
        _, previous, line, dots_only = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, line, dots_only)
    line = (line + token).rsplit('\n', 1)[-1][-160:]
    dots_only = dots_only and all(c == '·' for c in token)
    return (doc, token, line, dots_only), float(value)

programs.haiku:
"""Candidate 2: a short list of token-in-context rules, each with a typical value."""
READS = ()

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    same_doc = len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same_doc else ""
    if cur == "\xa0" and prev == " –":
        return carry, -2.1
    if cur == " grep":
        return carry, -1.0 if prev == " |" else -0.6
    if cur == "git":
        return carry, -1.5 if prev == " --" else -0.9
    if cur in (" null", " undefined", " None") and prev == " |":
        return carry, -1.1
    if cur == "Continue" and prev == " …":
        return carry, -0.8
    if cur == "permalink" and prev == "[#":
        return carry, -0.55
    if cur == " (@":
        return carry, -0.75
    if cur == "born":
        return carry, -0.26
    return carry, 0.0

programs.sol:
"""Predict horizontal padding and words immediately following pause punctuation.

Wide space/tab tokens produce positive pulses. Space-width bands have bumps
just before four-space boundaries; very long runs give smaller pulses.
Whitespace containing line breaks has a separate, weaker response. Short
whitespace has small responses, with exceptions for tab-plus-space tokens.
Real versus escaped preceding newlines adjust pure-space pulses.
After ellipses or dashes, words produce negative pulses, strongest for the
listed English function words. Other non-whitespace tokens predict zero.
The short text history resets at document boundaries.
"""
from functools import lru_cache

READS = ()
FUNCTION_WORDS = frozenset('''
a an the and but or so yet if as than that which while because though when
whether I you he she it we they there this these those my your his her our
their to of in on at for from with without by about into over under can
could will would might may should must have has had be is are was were not
only just also all
'''.split())
ELLIPSES = frozenset(('..', '...', '....', '......', '…'))
DASHES = frozenset(('--', '---', '—', '–'))


# Upper width and response for successive space-run bands.
SPACE_BANDS = (
    (6, 0.08), (7, 0.57), (9, 0.51), (10, 0.70),
    (12, 1.10), (14, 1.00), (20, 1.30), (32, 1.00), (64, 0.75),
)


def space_level(width):
    if width < 6:
        return 0.0
    value = next((level for limit, level in SPACE_BANDS if width <= limit), 0.40)
    if 15 <= width <= 64 and width % 4 == 3:
        value += 0.14 if width <= 20 else 0.30
    return value


@lru_cache(maxsize=2048)
def padding(text):
    if not text or any(c not in ' \t\n\r\u00a0' for c in text):
        return None
    spaces = text.count(' ') + text.count('\u00a0')
    tabs = text.count('\t')
    if '\n' in text or '\r' in text:
        if tabs:
            return min(0.73, max(0.0, 0.30 * (tabs - 2)))
        if spaces < 8:
            return -0.13 if spaces >= 3 else 0.0
        if spaces < 12:
            return 0.15
        return 0.30 + (0.38 if spaces % 2 == 0 else 0.0)
    if tabs and spaces >= 7:
        levels = (0.73, 1.07, 1.39, 1.44, 1.15, 1.07)
        level = levels[min((spaces - 7) // 4, 5)]
        return min(1.60, level + 0.36 * (tabs - 1))
    if tabs >= 2:
        levels = (0.67, 1.11, 1.32, 1.40)
        return levels[tabs - 2] if tabs <= 5 else 1.15
    if tabs:
        return (-0.02, -0.30, -0.19, -0.05)[spaces] if spaces < 4 else 0.02
    return space_level(spaces)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail = '' if fresh else carry[1]
    previous = '' if fresh else prefix.token_strings[-2].strip()
    value = padding(text)
    if value is not None:
        if set(text) <= {' '}:
            if len(text) == 3:
                value = 0.025 if tail.endswith('\n') else -0.08
            elif value > 0.0:
                if fresh:
                    value *= 1.30
                elif tail.endswith('\n'):
                    value *= 1.025
                else:
                    value *= 0.89 if tail.endswith('\\n') else 0.965
    else:
        word = text.strip()
        value = 0.0
        if previous in ELLIPSES or previous in DASHES:
            ellipsis = previous in ELLIPSES
            if word in FUNCTION_WORDS:
                value = -0.68 if ellipsis else -0.56
            elif word.isalpha() and word.islower():
                value = -0.31 if ellipsis else -0.21
                if not text.startswith(' '):
                    value -= 0.14
            elif word.isalpha() and not text.startswith(' '):
