"""Unit nouns: time periods (year, week, month, season, hour, day...), administrative
areas (district, county, zone...) and measures (dollar, mile, acre...).
The component fires on such a noun when it names the unit in running text; it is
suppressed when a number comes right before it ("3 year old")."""

READS = ()

TIME = {"year": 3.6, "week": 3.6, "quarter": 3.0, "month": 2.7, "hour": 2.4,
        "semester": 2.3, "season": 2.0, "decade": 2.2, "weekend": 1.5, "century": 1.3,
        "day": 1.3, "minute": 1.2, "night": 0.8, "morning": 0.8}
AREA = {"district": 1.6, "county": 1.2, "zone": 1.2, "sector": 0.9, "province": 0.7,
        "country": 0.6, "continent": 0.6}
MEASURE = {"dollar": 1.7, "mile": 1.7, "gallon": 2.0, "inch": 1.4, "yard": 1.5,
           "acre": 1.2, "foot": 1.0, "ounce": 1.1, "pound": 0.8}
UNITS = {**TIME, **AREA, **MEASURE}
DETERMINERS = {"the", "a", "an", "this", "that", "past", "next", "same", "previous"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" -_./").lower()
    base = UNITS.get(word, 0.0)
    if base == 0.0:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if before.isdigit():
        return carry, 0.15 * base          # "3 year old": a number before the unit
    if before in DETERMINERS:
