"""Local zero-context responses, with two smaller lexical patterns.

Digits 2–9 give increasing positive responses after ASCII zero; consecutive
zeros strengthen them. Decimal separators or spaces weaken it. One after
zero, and separators immediately after zero, have small negative responses.
Intestinal vocabulary gives a separate negative response. The chat-format
markers have small fixed offsets, particularly the end of a tool response.
These amplitudes summarize training observations, not all token-specific noise.
"""
READS = ()
DIGIT_RESPONSE = (0.01, -0.08, 0.234, 0.554, 0.733, 0.937,
                  0.998, 1.059, 1.160, 1.297)

# Conversation-format delimiters, not ordinary words.
MARKERS = {
    '<tool_response>': -0.065,
    '</tool_response>': -0.229,
    '<tool_call>': -0.021,
    '</tool_call>': -0.035,
    '<think>': -0.054,
    '</think>': 0.113,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        zeros, previous, zero_before_previous = 0, '', False
    else:
        _, zeros, previous, zero_before_previous = carry
    token = prefix.token_strings[-1]
    value = MARKERS.get(token, 0.0)
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        if zeros:
            value = DIGIT_RESPONSE[digit]
            if zeros > 1 and digit >= 2:
                value *= 1.20
            if digit == 0:
                value = 0.016 if zeros == 1 else -0.015
        elif zero_before_previous and previous in ('.', ',', ' '):
            # A separator weakens, but does not erase, the preceding zero.
            if digit == 1:
                value = -0.08 if previous != ',' else -0.023
            elif digit >= 2:
                scale = {'.': 0.30, ',': 0.25, ' ': 0.34}[previous]
                value = max(0.0, scale * DIGIT_RESPONSE[digit] - 0.05)
            elif previous == ' ':
                value = -0.07
        elif previous == '.':
            value = -0.04
    elif zeros:
        if token in ('-', '+'):
            value = -0.14
        elif token in ('.', ':', ';', '(', ')', '=', ' '):
            value = -0.05
        elif token == ',':
            value = -0.03
    word = token.strip().lower()
    if word in ('intestinal', 'intestine', 'intest', 'estinal'):
        spaced_adjective = word == 'intestinal' and token.startswith(' ')
        value = -1.08 if spaced_adjective else -0.87
    elif word in ('bowel', 'gastrointestinal'):
        value = -0.51
    elif word in ('腸', '肠'):
        value = -1.50
    elif word == '肠道':
        value = -1.02
    elif word == '肠胃':
        value = -0.62
    elif word == 'gut':
        value = -0.17
    next_zeros = zeros + 1 if token == '0' else 0
    return (doc, next_zeros, token, zeros > 0), float(value)

