"""Approximate this mostly quiet component with pulses on later number digits.

Harvested high-importance examples often place large responses on digits 3–9
after earlier digits. This coarse rule counts only consecutive digit tokens;
it ignores the surrounding number format and other context.
"""

READS = ()

HIGH_DIGITS = frozenset("3456789")
ALL_DIGITS = frozenset("0123456789")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    run = 0
    if carry is not None:
        previous_doc, previous_run = carry
        if doc == previous_doc:
            run = previous_run

    token = prefix.token_strings[-1]
    value = 0.0
    if token in HIGH_DIGITS:
        if run >= 3:
            value = 0.26
        elif run == 2:
            value = 0.11
        elif run == 1:
            value = 0.06
        else:
            value = 0.015

    if token in ALL_DIGITS:
        next_run = run + 1
    else:
        next_run = 0
    return (doc, next_run), value

