    (1.7, 'inflation deflation stagflation recession'),
    (1.2, 'economy economies economic economists policymakers'),
    (0.9, 'monetary fiscal reforms unemployment austerity wage wages earnings'),
    (0.7, 'tax taxes taxation tariffs reform crisis stimulus liquidity exports '
           'expenditure lending prosperity deficit'),
    (0.5, 'cost costs expensive costly market markets demand credit currency '
