CHINESE = [
    (5.0, '货币政策 貨幣政策 财政政策 財政政策'),
    (3.7, '通胀 通膨 加息 降息 美联储 美聯儲'),
    (2.6, '利率 油价 油價 汇率 匯率 全球经济 经济增长 增速 金价'),
    (1.8, '增长 增長 股市 央行 宏观 信贷 同比 房价 楼市 供需 '
           '复苏 中美 关税 结构性 贬值 回升'),
    (1.4, '经济 經濟 経済 政策 财政 財政 制造业 产量 供给 房地产 '
           '总量 调控 宽松 下行 过剩 走势 涨幅 万亿元 收益率'),
    (1.0, '改革 消费 消費 货币 貨幣 美元 外汇 贸易 貿易 出口 库存 '
