STEMS = [
    (1.1, ('econom', 'économ', 'экономик', '경제')),
    (0.65, ('эконом', 'conom', 'wirtschaft', 'irtschaft')),
    (1.6, ('inflation', 'flation', 'инфля', 'inflaci')),
    (0.8, ('monet', 'fiscal', '정책', 'налог', 'thuế')),
    (0.6, ('кредит', 'валют', 'рын', 'торгов')),
