        elif modifier in {'exchange', 'inflation', 'mortgage', 'funds'}:
            value = 1.8
        elif modifier in {'growth', 'tax', 'unemployment', 'discount'}:
            value = 1.5
        elif modifier in {'frame', 'filtration', 'transfection', 'any'}:
