            value = 1.0
        if modifier in {'hydrogen', 'chemical', 'covalent', 'ionic', 'double'}:
            value = -0.1
    elif w == 'supply':
        if modifier in {'money', 'monetary', 'global', 'domestic', 'aggregate'}:
            value = 2.0
        elif modifier in {'power', 'information', 'bench'}:
            value = 0.0
    elif w == 'development' and modifier == 'economic':
        value = 1.15
    elif w == 'spending' and modifier in {'consumer', 'government', 'public'}:
        value = 2.2
    elif w == 'fed':
        value = 0.85 if token.strip().startswith('F') else 0.08
    elif w == 'prices':
        value = 1.15 if economic else 0.75
        if modifier in {'consumer', 'equity', 'oil', 'asset'}:
            value = 1.8
    elif w == '息' and before.endswith(('降', '加')):
        value = 3.1

    if w in CJK and economic:
        value += 0.5
    if w == '政策' and before.endswith(('货币', '財政', '财政')):
        value = 4.7
    if w in {'增长', '增長'} and before.endswith(('经济', '經濟')):
