"""layers.0.mlp.down_proj:4817 -- fires on word-pieces mid-word and on code identifiers.

This component is a weak, mostly token-specific signal in layer 0's MLP. Its largest
positive responses are on:
  * short Latin-letter word pieces that begin in the middle of a word (no leading space)
    and end in a vowel followed by "t": "it", "at", "ut", "ot", "mit", "IT", "AT", "UT"
    (e.g. "OBS|ERV|ATION", "Dog|mat|ismus");
  * the word "super" (as in "nuclear super power"), the strongest single trigger;
  * common programming keywords and type names: int, null, var, val, const, dict, Math.
Most other tokens are near zero. Negative responses are scattered (e.g. "char", "Vec",
"bin") and are not predicted here.

The program reads only the current token and the previous one:
  * "super" -> 0.6;
  * a word-piece of 2 to 4 ASCII letters, no leading space, ending in vowel + t -> 0.14,
    or 0.20 if the previous token was also such a piece (a word split into pieces);
  * a programming keyword or type name -> 0.05;
  * anything else -> 0.
The carry is unused. The rules are local, so they reset at document boundaries
automatically.
"""

READS = ()

SUPER = {"super"}
CODE = {
    "int", "null", "var", "val", "const", "def", "lib", "min", "max", "dict", "str",
    "class", "object", "import", "func", "fun", "num", "bool", "port", "Port", "Int",
    "Math", "math", "cur", "init", "format", "char", "float", "void", "new", "return",
    "self", "true", "false", "nil", "None", "list", "array", "byte", "struct", "type",
    "enum", "string", "data", "attr", "param", "dist", "exit", "url", "assert",
}
VOWELS = set("aeiouAEIOU")


def _is_piece(s):
    """A short ASCII letter fragment with no leading space, ending in vowel + t."""
    return (
        2 <= len(s) <= 4
        and s[0] != " "
        and s.isascii()
        and s.isalpha()
        and s[-1] in "tT"
        and s[-2] in VOWELS
    )


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    word = s.strip()
    if word in SUPER:
        return None, 0.6
    if _is_piece(s):
        same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_doc and _is_piece(prefix.token_strings[-2]):
            return None, 0.20
        return None, 0.14
    if word in CODE:
        return None, 0.05
    return None, 0.0

