"""Approximate a sparse response to conspicuous symbols and repeated typography.

Percent and at signs, ellipses, double dashes, mathematical scripts and
nonbreaking spaces are positive triggers. Long character runs also respond;
newlines bundled into a token usually weaken them. A few literal disc/disk,
throw and ignore word fragments are secondary triggers, not a semantic rule.
Everything else gets zero. The three-character carry recognizes split LaTeX
commands and script braces, and resets at document boundaries.
"""
import math
import re

READS = ()
THROW_FORMS = {'throw', 'throws', 'thrown', 'throwing', 'threw'}
DISK_CHARACTERS = {'盘', '盤', '碟'}
RUN_SYMBOLS = set('-=_~*#/$^\\.·・¯!')


def repeated_typography(s, spaced, newline):
    runs = re.finditer(r'(\S)\1+', s)
    run = max(runs, key=lambda m: len(m[0]), default=None)
    if run is None:
        return 0.0
    ch, n = run[1], len(run[0])
    if '--' in s and n == 2 and not any(c in s for c in '<>'):
        return 0.53 + 0.09 * spaced - 0.25 * newline
    if s == '---':
        return 0.13 - 0.30 * newline
    if s in {'~~', '——', '··', '・・・'}:
        return 0.38
    letter = ch.isascii() and ch.isalpha()
    if n < 4 or not (ch in RUN_SYMBOLS or letter):
        return 0.0
    # Response grows to a medium-length run, then slowly falls for huge runs.
    length = math.log2(n)
    value = 0.52 + 0.31 * (length - 2) - 0.42 * max(0.0, length - 4)
    value += 0.16 * spaced - 0.27 * newline - 0.35 * (len(s) > n)
    value += 0.17 * (ch in '*~') + 0.52 * (ch == '^') + 0.25 * letter
    value -= 0.16 * (ch == '_') + 0.52 * (ch == '#' and n <= 6)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    joined, s = tail + text, text.strip()
    spaced, newline = text.startswith(' '), '\n' in text or '\r' in text
    word = s.lstrip('_-/').lower()
    value = 0.0
    if '\xa0' in text:
        value = 0.70 if text.count('\xa0') >= 3 else 0.60
        if text == '\xa0':
            value = 0.13
        elif text == '\xa0\xa0':
            value = 0.54
        if newline:
            value = 0.27
    elif '@' in s:
        value = 1.0 if s == '@' else 0.75 if len(s) <= 5 else 0.45
        if s.endswith(('"', '{')):
            value *= 0.5
    elif '＠' in s or '％' in s:
        value = 0.50
    elif '%' in s:
