"""A repeated-list-separator signal, strongest on bare commas.

Short comma-separated spans and dense lists raise the response. Nearby colons,
semicolons, periods, and East Asian commas also support this reading. Commas
fused with line breaks do not continue the list signal. The preceding token's
length, spacing, and capitalization supply small corrections; contrastive
words weaken the comma response. Periods also respond to single letters and
short line labels. Other tokens predict zero. History resets between documents.
"""
from collections import deque
from math import exp
import re

READS = ()
CONTRAST = frozenset('however alternatively nevertheless nonetheless moreover '
                     'furthermore instead otherwise'.split())
SEPARATORS = ',.:;，、)'
# Transfer of recent punctuation to the comma response.
RELATED = {'.': .30, ':': .44, ';': .67, '，': 1.02, '、': .50}
# Background, repetition amplitude, and decay length for weaker separators.
WEAKER = {':': (.10, .35, 8), ';': (.22, .70, 9),
          '，': (-.03, 1.50, 5), '、': (.07, .95, 3),
          ')': (.01, .08, 15)}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, {}, deque(), '', '', '')
    _, position, last, commas, previous, word, line = carry
    token = prefix.token_strings[-1]
    while commas and position - commas[0] > 128:
        commas.popleft()
    distance = position - last.get(',', -10000)
    tight_list = 1 / (1 + (distance / 4.5) ** 4)
    density = sum(exp(-(position - p) / 64) for p in commas)
    response = (-.068 + 1.27 * tight_list + .59 * exp(-distance / 8)
                + .036 * density - (.75 if distance == 1 else 0))
    response += sum(weight * exp(-(position - last.get(mark, -10000)) / 6)
                    for mark, weight in RELATED.items())
    value = 0.0
    mark = token.strip()
    preceding = previous.strip()
    if token == ',':
        value = response + .83 * exp(-position / 1.2)
        value -= .016 * len(preceding)
        if preceding.isalpha() and not previous.startswith(' '):
            value += .16
        if preceding.istitle():
            value += .09
        if word.lower() in CONTRAST:
            value -= .58
    elif ',' in token and '\n' not in token:
        if mark == ',':
            value = .65 * response
        elif any(c.isalnum() for c in token):
            value = .12 + .18 * response
        else:
            value = .55 * exp(-distance / 12) - .10 * exp(-distance / 40)
    elif token == '.':
        bare_distance = position - last.get('bare_period', -10000)
        period_distance = position - last.get('.', -10000)
        value = (-.08 + .33 * exp(-bare_distance / 10)
                 + .27 * exp(-period_distance / 10))
        if len(preceding) == 1 and preceding.isalpha():
            value += .19
        if '.' in previous:
            value -= .14
        if len(line.strip()) < 5:
            value += .27
        value -= .24 * exp(-position / 1.2)
    elif mark in WEAKER and '\n' not in token:
        background, amplitude, decay = WEAKER[mark]
        gap = position - last.get(mark, -10000)
        value = background + amplitude * exp(-gap / decay)
        if token.startswith(' '):
            value -= .08
    for separator in SEPARATORS:
        if separator in token and not (separator == ',' and '\n' in token):
            last[separator] = position
    if ',' in token and '\n' not in token:
        commas.append(position)
    if token == '.':
        last['bare_period'] = position
    match = re.search(r'([^\W\d_]+)$', token)
    word = ((word + match[0] if token.isalpha() else match[0])[-40:]
            if match else '')
    line = (line + token).split('\n')[-1][-40:]
    return (doc, position + 1, last, commas, token, word, line), float(value)

