"""Comma-in-a-list detector for layers.0.mlp.down_proj:4819.

The component fires on the comma (or other list separator) that closes one item of a
list of parallel items, e.g. "comedies, dramas, documentaries, ...". Its size depends on:
- how recently the previous comma came: a list of short items (gap of 1-2 words) gives
  the strongest response, and it fades over ~10 tokens;
- the item before the comma: a number or a capitalised name (a list of numbers or names)
  adds a little;
- discourse commas such as "however," "for example," or "Alternatively," give nothing;
- commas after CJK text (Chinese-style lists) are weaker.
Everything else is predicted as 0.
"""
import math

READS = ()

# How strongly each separator responds, relative to a comma.
SEPARATORS = {",": 1.0, "，": 1.0, "、": 0.5, ";": 0.5, ":": 0.3, ".": 0.25}
COMMA_LIKE = {",", "，", "、"}
# Sentence-opening words whose following comma is an interjection, not a list item.
INTRO_WORDS = {"however", "alternatively", "therefore", "thus", "example", "instead",
               "moreover", "yes", "true", "case", "time", "hence"}


def is_cjk(text):
    return any("一" <= c <= "鿿" for c in text)


def step(carry, prefix, upstream):
    t = prefix.position
    new_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    last_comma = None if (new_doc or carry is None) else carry
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if t > 0 else ""
    value = 0.0
    if tok in SEPARATORS:
        if last_comma is None:
            value = 0.1
        else:
            gap = t - last_comma
            value = 1.8 * math.exp(-(gap - 2) / 3) + 0.1
        if prev.strip().isdigit():
            value += 0.2
        elif prev.strip()[:1].isupper():
            value += 0.13
        if is_cjk(prev):
            value -= 0.2
        if prev.strip().lower() in INTRO_WORDS:
            value = 0.0
        value *= SEPARATORS[tok]
    if tok in COMMA_LIKE:
        last_comma = t
    return last_comma, value

