    run = max(re.finditer(r'_+', text), key=lambda m: len(m[0]))
    n = len(run[0])
    before, after = text[:run.start()], text[run.end():]
    if n == 1:
        value = 0.20
        if not before:
            if previous.endswith('_'):
                value = 1.0
            elif previous.strip().isupper():
                value = 0.27
            elif previous[-1:].isalnum():
                value = 0.14
        if '{' in after:
            return -0.10
        return value * (0.5 if after and not after.isspace() else 1.0)
    value = 1.73 if n == 2 else 3.17 if n == 3 else (
        5.25 - max(0.0, math.log2(n / 16)))
    if before.isspace():
        value += 1.0 if n < 4 else 0.5
    elif before == '.':
        value += 0.45
    elif any(c in before for c in '(\'"'):
        value -= 0.45
    elif not before and previous.endswith('_') and n == 2:
        value += 0.40
    if after:
        value *= 0.5 if after.isspace() or after == '/' else 0.25
