    mark = '?' if '?' in text else '？'
    before, after = text.split(mark, 1)
    value = 0.28 if mark == '？' else 0.39
    if before.isspace():
        value += 0.13
    if '\n\n' in after:
        value -= 0.35
    elif '\n' in after:
        value -= 0.25
    elif after and not after.isalpha() and not set(after) <= {'?'}:
        value -= 0.25
    return max(0.0, value)


