    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if '_' in text and not any(c.isalnum() for c in text):
        value = underscore(text, previous)
    elif '?' in text or '？' in text:
        value = question(text)
