            value = -0.60 if lower == 'one' else -0.53
            if before in {'no', 'least'}:
                value = -0.055
            elif before in {'only', 'exactly', 'each'}:
                value = -0.34
            elif before in {'first', 'second', 'third', 'every', 'any'}:
                value = -0.25
            elif before in {'a', 'this', 'just', 'last', 'other'}:
                value = -0.42
        else:
            value = -0.17 if lower == 'one' else -0.06
    elif lower == 'times':
        value = -1.0 if spaced or word[0].isupper() else -0.21
        if spaced and word.islower():
            if (before in NUMBER_WORDS
                    or before in {'many', 'several', 'multiple', 'few'}):
                value = -1.6
            elif before in {'modern', 'recent'}:
                value = 0.0
            elif before in {'at', 'all'}:
                value = -0.23
    elif lower in {'fois', 'vez', 'volta'}:
        value = {'fois': -2.6, 'vez': -1.6, 'volta': -1.4}[lower]
        if lower == 'fois' and before in {'une', "'une"}:
            value = -4.6
        elif lower == 'vez' and before == 'una':
            value = -4.5
        elif lower == 'volta' and before == 'una':
            value = -2.4
        if not spaced and word.islower():
            value = -0.99 if lower == 'fois' else 0.0
    elif lower in FREQUENCY_ADVERBS:
        value = FREQUENCY_ADVERBS[lower]
        if lower == 'sometimes' and word[0].isupper():
            value = -0.72 if spaced else -0.90
    elif lower in OCCURRENCES:
        value = OCCURRENCES[lower]

    if value == 0.0 and before == 'once':
        if lower == 'you':
            value = -1.0
        elif lower in {'the', 'an', 'we', 'it'}:
            value = -0.6
        elif lower in {'a', 'i', 'they', 'your', 'upon'}:
            value = -0.36

