"""Approximate the component with short, adjacent-token English phrases.

The strongest pulse is the continuation of 'what', especially 'is', 'was',
or contracted 's'. Related question words, contracted 'that's'/'here's',
and continuations of 'all' give smaller pulses. A few common contractions
and 'it was' are also recognized. Only the preceding token is remembered;
a new document resets it. Most text is left at zero.

Training activations peak on these continuations, not on the question
word itself. Smaller, scattered lexical responses are not reconstructed.
"""

READS: tuple[str, ...] = ()

WHAT_AUXILIARIES = {
    'is': -1.71, 'was': -1.58, 'are': -1.30, 'were': -1.0,
    'would': -1.09, 'will': -1.10, 'should': -0.93,
    'can': -0.72, 'could': -0.74, 'might': -0.59,
    'do': -0.54, 'does': -0.51, 'did': -0.65,
    'has': -0.59, 'have': -0.55, 'had': -0.55, 'am': -0.70,
}
WHAT_OTHER = {
    'to': -0.80, 'kind': -0.70, 'about': -0.55, 'it': -0.45,
    'not': -1.0, 'really': -1.0, 'the': -0.24, 'if': -0.27,
}
ALL_CONTINUATIONS = {
    'of': -0.61, 'over': -0.61, 'time': -0.50, 'times': -0.70,
    '-time': -0.55, 'out': -0.44, 'was': -0.50,
    'in': -0.32, '-in': -0.54, 'day': -0.42, 'around': -0.39,
    'but': -0.36, 'too': -0.56,
    'the': -0.14, 'these': -0.14, 'that': -0.25, 'this': -0.25,
}
QUESTION_SCALE = {'how': 0.36, 'why': 0.31, 'where': 0.42}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    word = prefix.token_strings[-1].strip().lower()
    previous = carry[1] if carry is not None and carry[0] == document else ''
    contraction = word in ("'s", '’s')
    value = 0.0
    if previous == 'what':
        if contraction:
            value = -2.31 if word == '’s' else -2.21
        else:
            value = WHAT_AUXILIARIES.get(word, WHAT_OTHER.get(
                word, -0.18 if word.isalpha() else 0.0))
    elif previous == 'all':
        value = ALL_CONTINUATIONS.get(word, -0.18 if word.isalpha() else 0.0)
    elif contraction and previous in ('that', 'here', 'who'):
        value = {'that': -0.58, 'here': -0.31, 'who': -0.84}[previous]
        if word == '’s':
            value -= 0.07
    elif contraction and previous == 'where':
        value = -1.16 if word == "'s" else -1.23
    elif word in ("'re", '’re') and previous in ('you', 'we', 'they'):
        value = -0.18 if word == "'re" else -0.22
    elif word in ("'m", '’m') and previous == 'i':
        value = -0.08 if word == "'m" else -0.12
    elif previous == 'it' and word == 'was':
        value = 0.23
    elif previous in ('kind', 'kinds', 'sort', 'sorts') and word == 'of':
        value = -0.23
    elif previous in QUESTION_SCALE and word in WHAT_AUXILIARIES:
        value = QUESTION_SCALE[previous] * WHAT_AUXILIARIES[word]
        if word in ('do', 'does', 'did'):
            value *= 1.65
    elif previous == 'who' and word in ('is', 'was', 'were'):
        value = -0.21 if word == 'were' else -0.31
    return (document, word), value

