OTHER_WH = {"who", "how", "where", "why", "when", "whatever"}
ALL_AFTER = {"of", "over", "times", "time", "day"}
CONTRACTIONS = {"'s", "’s", "'re", "’re"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    prev = toks[-2].strip().lower()
    cur = toks[-1].strip().lower()
    if prev == "what":
        if cur in COPULA_AFTER_WH:
            return carry, COPULA_AFTER_WH[cur]
        if cur in MODAL_AFTER_WH:
            return carry, MODAL_AFTER_WH[cur]
    if prev in OTHER_WH and cur in COPULA_AFTER_WH:
        return carry, -0.5
    if prev in OTHER_WH and cur in {"do", "does", "can", "will"}:
        return carry, -0.4
    if prev == "that" and cur in CONTRACTIONS:
        return carry, -0.6
    if prev == "here" and cur in CONTRACTIONS:
        return carry, -0.3
    if prev == "all" and cur in ALL_AFTER:
        return carry, -0.6
    if prev == "kind" and cur == "of":
        return carry, -0.3
    if prev in {"it", "there"} and cur == "was":
        return carry, 0.2
