"""Recognizes common continuations of questions and broad quantity words."""
READS = ()


QUESTION_WORDS = {"what", "who", "where", "when", "why", "how"}
BE_WORDS = {"is", "are", "was", "were"}
AUXILIARIES = {
    "do", "does", "did", "would", "will", "can", "could",
    "should", "has", "have", "had",
}


def step(carry, prefix, upstream):
    n = len(prefix.token_strings)
    if n < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip().lower()
    current = prefix.token_strings[-1].strip().lower().replace("’", "'")

    if previous in QUESTION_WORDS:
        if current in BE_WORDS:
            if previous == "what" and current == "is":
                return None, 0.6 * -1.7
            if current == "are":
                return None, 0.6 * -1.3
            return None, 0.6 * -0.6
        if current in AUXILIARIES:
            if previous == "what" and current == "would":
                return None, 0.6 * -1.05
            return None, 0.6 * -0.6
        if previous == "what" and current == "it":
            return None, 0.6 * -0.5
        if current in {"'s", "'re", "'d", "'ve"}:
            return None, 0.6 * (-2.25 if previous == "what" else -0.6)

    if previous == "that" and current in {"'s", "'re", "'d", "'ve"}:
        return None, 0.6 * -0.63
    if previous == "all":
        return None, 0.6 * -0.6
    return None, 0.0

