"""Lexical approximation of pulses on verbal arithmetic, not its symbols.

Space-prefixed operator words produce negative pulses, stronger near numbers
or math notation. 'Equal to' is especially strong. Roots and operation
prepositions have phrase-specific responses; informal speech words also fire.
Space-prefixed sum/product/total have small positive responses. Most unspaced
variants are ignored or attenuated; other tokens predict zero.
Only the previous token and twelve math-cue flags are retained, resetting
between documents. Diffuse smaller token-specific activations are not modeled.
"""
READS = ()

NUMBER_WORDS = set('zero one two three four five six seven eight nine ten '
                   'eleven twelve hundred thousand million'.split())
# Each triple is: prose, recent math cues, immediately after a number.
OPERATORS = {
    'times': (-0.18, -0.50, -0.80),
    'plus': (-0.32, -0.66, -1.16),
    'divided': (-0.28, -0.50, -0.72),
    'negative': (-0.27, -0.50, -0.79),
    'positive': (-0.15, -0.30, -0.50),
    'equal': (-0.46, -0.57, -0.63),
    'equals': (-1.16, -1.25, -1.55),
    'minus': (-1.28, -1.47, -1.88),
    'squared': (-0.83, -0.96, -1.16),
    'over': (0.0, -0.05, -0.22),
    'off': (-0.07, -0.11, -0.31),
}
MATH_WORDS = {
    'divide': -0.27, 'multiply': -0.44, 'multiplied': -0.87,
    'multiplying': -0.33, 'multiplication': -0.25,
    'subtract': -0.55, 'subtraction': -0.39,
    'square': -0.10, 'cube': -0.18, 'root': -0.06,
    'factorial': -0.30, 'parenthesis': -0.46, 'parentheses': -0.46,
    'zero': -0.11, 'percent': -0.10, 'twice': -0.17,
    'numerator': -0.22, 'denominator': -0.17, 'infinity': -0.21,
    'sum': 0.05, 'total': 0.12, 'product': 0.11,
}
SPEECH_WORDS = {
    'okay': -0.42, 'yeah': -0.50, 'hmm': -0.33, 'um': -0.17,
}
# Responses on the second token of arithmetic collocations.
PHRASES = {
    'equal to': -1.49, 'equals to': -1.30,
    'divided by': -0.59, 'multiplied by': -0.59,
    'divide by': -0.30, 'multiply by': -0.30,
    'cancel out': -0.70, 'factor out': -0.42,
    'square root': -0.45, 'cube root': -0.45, 'double root': -0.45,
    'is equal': -0.66, 'is negative': -0.71, 'is positive': -0.47,
    'mean squared': -0.46, 'of squared': -0.46,
}
RELATIONS = {'proportional', 'perpendicular', 'adjacent', 'equivalent'}
FREQUENCY = {'many', 'several', 'all', 'at', 'multiple', 'some'}
CONTRACTIONS = {"'m", "'re", "'s", '’m', '’re', '’s'}
CUE_WORDS = (OPERATORS.keys() - {'over', 'off'}) | {
    'divide', 'multiply', 'multiplied', 'subtract', 'square', 'cube', 'root',
} | NUMBER_WORDS | {'x', 'y', 'z', 'n', 'k'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, recent = ('', ()) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    number = previous.isdigit() or previous in NUMBER_WORDS
    context = 2 if number else int(any(recent))
    value = 0.0
    if token.startswith(' '):
        if word in OPERATORS:
            value = OPERATORS[word][context]
        else:
            value = MATH_WORDS.get(word, SPEECH_WORDS.get(word, 0.0))
        value = PHRASES.get(previous + ' ' + word, value)
        if word == 'times' and previous in FREQUENCY:
            value = -0.10
        elif word == 'to' and previous in RELATIONS:
            value = -0.21
        elif word == 'gonna':
            value = -1.18 if previous in CONTRACTIONS else -0.66
        if token.strip() == 'Times':
            value = -0.30
        elif token.strip() == 'Plus':
            value = -0.65
    elif word in OPERATORS and word not in {'over', 'off'}:
        value = OPERATORS[word][1] * (1.0 if word == 'plus' else 0.4)
    elif word in {'multiply', 'okay', 'yeah'}:
        value = MATH_WORDS.get(word, SPEECH_WORDS.get(word, 0.0))
    elif token == 'Hmm':
        value = -0.10
    elif token == 'ing' and previous == 'subtract':
        value = -0.42
    cue = (word in CUE_WORDS
           or any(c.isdigit() or c in '=+*/^²³√±≤≥∑∞' for c in token))
    return (doc, word, (recent + (cue,))[-12:]), float(value)

