"""Spelled-out arithmetic operation words make this component go negative: the word for
minus/equals/times/divided/squared/plus/multiply/subtract/negative. The symbols (+ - = x /)
and words like sum, product, add or ratio do not. The strength is roughly the word's typical
activation. 'to' right after 'equal' (equal to) and 'by' after 'divided'/'multiplied' also
go negative, and so do a few filler words in spoken maths ('Hmm', 'okay', 'yeah', 'gonna').
Everything else predicts 0."""

# typical activation of each operation word
OPS = {
    " minus": -1.3, " equals": -1.2, " Equals": -0.6, "equals": -0.5, " equal": -0.55,
    " squared": -1.0, " multiplied": -0.85, " multiply": -0.45, " multiplying": -0.35,
    " Multiply": -0.7, " times": -0.5, " Times": -0.3, " divided": -0.5, " divide": -0.25,
    " Plus": -0.65, " plus": -0.5, "plus": -0.5, " subtract": -0.55, " subtraction": -0.4,
    " negative": -0.5, " positive": -0.3, " parentheses": -0.5, " factorial": -0.35,
}
FILLERS = {" Hmm": -0.35, " okay": -0.4, " Okay": -0.4, " yeah": -0.5, " gonna": -0.9}
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    n = len(prefix)
    same_doc = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    if token == " to" and before in (" equal", " equals"):
        value = -1.5
    elif token == " by" and before in (" divided", " multiplied"):
        value = -0.55
    elif token in OPS:
        value = OPS[token]
    elif token in FILLERS:
        value = FILLERS[token]
    else:
        value = 0.0
    return carry, float(value)

