def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('.')
    lower = word.lower()
    value = 0.0
    if word == 'Wait':
        value = 0.61 if token == 'Wait' else 0.57
    elif lower == 'wait':
        value = 0.45 if token[:1].isspace() else 0.39
    elif lower in {'waiting', 'waited', 'waits', 'await', 'awaiting'}:
        value = 0.31 if lower == 'waiting' else 0.25
    elif lower in {'awaited', 'awaits'}:
        value = 0.09
    elif lower == 'waitfor':
        value = 0.35
    elif word == '等待':
        value = 0.42
    elif lower in {'delay', 'delayed', 'delays'}:
        value = 0.14 if lower == 'delay' else 0.08
    elif word == 'Hmm':
        value = 0.13 if token == word else 0.095
