"""A spelling-based approximation to a vowel-join component.

Trigger on an unspaced alphabetic token starting with a vowel (or y)
when the previous token ends in a vowel. Single vowels and short
inflection-like tails are positive; longer fragments are negative.
Length, case, consonants and common affixes adjust the fitted strength.
At a document/start marker, use the current token's final letter with
reduced strength. Everything else is zero. This captures the main
join pattern, not the component's individual-token/background variation.
"""
import unicodedata

READS = ()
LATIN = 'aeiou'
CYRILLIC = 'аеёиоуыэюя'
GREEK = 'αεηιουω'
AFFIXES = {'ing', 'ion', 'ions', 'ation', 'ations', 'able', 'ible'}


def vowel(c):
    if c in 'йЙ':
        return False
    base = unicodedata.normalize('NFD', c.lower())[:1]
    return bool(base) and base in LATIN + CYRILLIC + GREEK


def response(s, previous=''):
    n, low = len(s), s.lower()
    last = previous[-1:].lower()
    if not s.isascii():
        if n > 1:
            return -0.08
        if low in CYRILLIC:
            return 0.7
        if low in 'ιίύ':
            return 0.7
        return 0.25
    if n > 1 and s[0].isupper() and not s.isupper():
        return 0.0
    if n == 1:
        if low == 'y':
            return 0.3
        value = 0.75 - 0.25 * (low == 'o') - 0.1 * s.isupper()
        return value + 0.3 * (last in 'ae' and bool(last))
    if n == 2:
        value = 0.05 + 0.2 * (low[0] == 'u') - 0.2 * (low[0] == 'o')
        end = low[-1]
        if end == 'n':
            value += 0.4
        elif end == 's':
            value += 0.5
        elif end in 'rl':
            value += 0.15
        elif end == 't':
            value += 0.1
        elif end in 'bcfgkpqvxz':
            value -= 0.45
        elif end in 'yw':
            value -= 0.55
        return value + 0.25 * (last == 'e')
    if n <= 4:
        value = -0.45 if n == 3 else -0.5
    else:
        value = -0.35 if n <= 6 else -0.1
    value -= 0.15 * (low[-1] in LATIN)
    value -= 0.45 * ('k' in low)
    value -= 0.1 * any(c in low for c in 'gvwjy')
    value += 0.35 * (low in AFFIXES)
    value += 0.5 * (n == 3 and low.endswith('s'))
    value += 0.2 * s.isupper()
    return value - 0.2 * (last == 'a') + 0.05 * (last == 'e')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    at_start = not previous or previous.startswith('<|')
    before = token if at_start else previous
    value = 0.0
    if before and token and token.isalpha():
        if vowel(before[-1]) and (vowel(token[0]) or token[0].lower() == 'y'):
            value = response(token, '' if at_start else previous)
            if at_start:
                value *= 0.7
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP component 4830 (down_proj): a word-fragment detector, signed by piece length.

It reads the MLP's hidden state, and the activation is large only inside a word that the
tokenizer split into pieces. Concretely, it fires on a Latin-letter piece with no leading
space that follows another Latin-letter piece ending in a vowel. Whole words, word-initial
pieces and most common endings (-ing, -ers, -ation, -ed) predict 0.

Within those fragments the sign follows the piece's length:
  * one letter (e, i, a, u, ...)  -> positive, e.g. "Nymphalida|e", "Malere|i";
  * two letters                   -> weakly positive, e.g. "Levenshte|in" (3 letters: negative);
  * three to five letters         -> negative, e.g. "Ha|iku", "Lu|igi", "Swe|eter", "da|ichi";
  * six or more letters           -> about 0.

The values are rounded means measured on training rows. They explain only a few percent
of the variance: most of the energy is in per-token, per-context details (rare fragments
like "iku", "ichi", "ethyl") that a short concept cannot list.
"""

READS = ()

VOWELS = set("aeiou")

# piece length -> activation, for a Latin piece after a vowel-ending Latin piece
BY_LENGTH = {1: 0.33, 2: 0.12, 3: -0.2, 4: -0.22, 5: -0.14}


def _latin_piece(text):
    return text.isascii() and text.isalpha()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    piece, before = prefix.token_strings[-1], prefix.token_strings[-2]
    if not (_latin_piece(piece) and _latin_piece(before)) or before[-1] not in VOWELS:
        return carry, 0.0
    return carry, BY_LENGTH.get(len(piece), 0.0)

