"""Approximate a chapter/section-marker feature.

Chapter words and 章 receive a large negative response; section labels,
other document divisions and chapter-like word pieces receive smaller ones.
Join split words, and briefly extend English references into spaces/numbers.
Ignore the many small lexical responses outside this family.
"""
import re

READS = ()
CHAPTER_TRANSLATIONS = {
    'chapitre', 'chapitres', 'capitolo', 'capitoli',
    'capítulo', 'capítulos', 'capitulo', 'capitulos', 'kapitel', 'capitel',
}
# Prefixes and endings of chapter words, including Romance/German spellings.
CHAPTER_PIECES = {
    'chap': 2.5,
    'capit': 1.5,
    'kap': 0.85,
    'cap': 0.5,
    'pter': 0.85,
    'apter': 0.85,
    'apters': 0.85,
    'ap': 0.3,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, previous, reference, age = (doc, '', 0.0, 0) if first else carry
    text = prefix.token_strings[-1]
    token = text.strip()
    word = token.lstrip('./_-').casefold()
    joined = previous + text if text[:1].isalpha() else text
    match = re.search(r'[^\W\d_]+$', joined)
    formed = match.group()[-24:] if match else ''
    whole = formed.casefold()
    chapter = word in {'chapter', 'chapters'} or (
        whole in {'chapter', 'chapters'} and len(word) >= 4
    )
    section = word in {'section', 'sections'} or '§' in token
    size = 0.0
    if chapter:
        size = 6.5
        if token.isupper() or whole == 'chapters':
            size = 5.5
        elif token == 'Chapter' and not text.startswith(' '):
            size = 7.2 if first else 5.5
    elif token == '章':
        size = 4.5 if previous.endswith(('党', '奏', '简')) else 6.5
    elif token == '章节':
        size = 7.0 if previous.endswith('最新') else 5.2
    elif token.startswith('第') and token.endswith('章'):
        size = 4.8
    elif token == '篇章':
        size = 2.3
    elif whole in CHAPTER_TRANSLATIONS:
        size = 0.9 if word in {'s', 're', 'res'} else 4.6
        if whole == 'capitel':
            size = 3.1
    elif word == 'глав' or whole == 'chương':
        size = 2.8
    elif whole in {'глава', 'главе', 'главу', 'глави', 'главы', 'главой'}:
        size = 2.6 if whole in {'главы', 'главой'} else 3.9
    elif section:
        size = 1.25 if word.endswith('s') else 1.5
        if not text.startswith(' ') or token.isupper() or '§' in token:
            size = 1.0
        elif token.istitle():
            size += 0.25
        if previous.casefold() in {'cross', 'inter'}:
            size = 0.4 if previous.casefold() == 'cross' else 0.15
    elif word == 'ch':
        size = 0.4 if text.startswith(' ') or token.isupper() else 0.18
        if token == 'Ch':
            size = (1.76 if text.startswith(' ') else 2.17) if first else 0.8
        elif token.lstrip('./_-') != token:
            size = 0.65
    elif word in CHAPTER_PIECES:
        size = CHAPTER_PIECES[word]
    elif whole == 'chap':
        size = 2.5
    elif word == 'contents':
        size = 1.9 if previous.casefold() == 'of' else 0.8
    elif word == 'appendix':
        size = 1.2
    elif word in {'subsection', 'subsections', 'sect', 'раздел'}:
        size = 0.8
    elif word in {'paragraph', 'paragraphs', 'subparagraph', 'subparagraphs'}:
        size = 0.5
    elif token in {'第', '節', '节', '段', '篇', '장', '제'}:
        size = 0.8 if token == '第' else 0.7

    new_reference = size if chapter or section else 0.0
    if reference:
        if not token or token.isdigit():
            size += reference * 0.15 * 0.55 ** age
        elif age == 0 and word in {'of', 'in'}:
            size += reference * (0.38 if word == 'of' else 0.06)
        elif age == 0 and token.isupper() and set(token) <= set('IVXLCDM'):
            size += reference * 0.1
    if new_reference:
        reference, age = new_reference, 0
    else:
        age += 1
        if age >= 4 or (token and not token.isdigit()):
            reference = 0.0
    return (doc, formed, reference, age), float(-size)

