programs.sol:
"""Detect tab-bearing whitespace, especially several tabs in a single token.

Numbers before the tabs and early document positions strengthen the response.
Trailing newlines or spaces weaken it. Tokens containing text, rather than
just whitespace, receive zero. All state resets at document boundaries.
"""
READS = ()


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    state = (doc, position + 1, token)
    if '\t' not in token or not token.isspace():
        return state, 0.0

    tabs = token.count('\t')
    numbered = previous.isdigit()
    single = tabs == 1
    if not token.strip('\t'):
        value = 0.71 if single else 2.70 if tabs == 2 else 3.15
        if numbered:
            value += 0.31 if single else 1.05
        elif previous and not previous.endswith('\n'):
            value += (0.08 if previous.isspace() else 0.15) if single else 0.75
        value += (0.38 if single else 1.0) / (1 + position / 30)
        if position == 0:
            value = 1.53 if single else 5.5
    elif '\n' in token:
        value = (0.40 + 0.39 * numbered) if single else (1.3 + 0.6 * numbered)
        if token.count('\n') > 1:
            value *= 0.65
        if single and '\r' in token:
            value -= 0.15
        if ' ' in token:
            value = 0.16
    elif token.endswith('\t'):
        value = 2.6 if token.startswith(' ') else 0.8 + 0.6 * tabs
    else:
        spaces = token.count(' ')
        value = 0.36 * min(tabs, 3) / max(1, spaces)**0.5 if spaces <= 2 else 0.0
        if single and spaces >= 16:
            value = -min(0.6, 0.04 * (spaces - 13))
    return state, float(value)

