"""Estimate the activation from the kind of tab whitespace in the current token."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    tabs = token.count("\t")
    if not tabs:
        return None, 0.0
    if " " in token:
        return None, 0.0
    if tabs > 1:
        return None, 1.1 if "\n" in token else 3.4
    return None, 0.7 if "\n" in token else 0.5

programs.sol:
"""Literal escapes and markup control words, not ordinary word meanings.

The main response is negative on letters immediately following a backslash;
escaped closing punctuation has the opposite sign. Familiar mathematical
symbols are weak, unlike text and formatting commands. Split style commands
and single-token escapes have smaller responses. State resets per document.
"""
READS = ()

GREEK = set('''alpha beta gamma delta epsilon zeta eta theta iota kappa
lambda mu nu xi pi rho sigma tau upsilon phi chi psi omega'''.split())
SYMBOLS = set('''sqrt times pm le ge neq approx equiv infty int sin cos tan
log ln rightarrow leftarrow Rightarrow Leftarrow prime sim vert Vert
langle rangle subseteq ell circ cdot frac notin angle oint longrightarrow'''.split())
OPERATORS = set('''sum prod exp partial cap cup subset sup inf min max
mod mid bullet ast star det gcd lcm'''.split())
LAYOUT = set('''left display math mathrm begin label cite item hat til wid
wide tilde dots boxed rm subsection lim limits quad'''.split())
TEXT_CONTROLS = set('''text big bold bar cal new rule code color section phantom
phant emph em ref vec over var ce'''.split())
SUFFIXES = set('''bb bf cal fr sf it scr op rm tt sc up normal style color
symbol name box note command'''.split())
TAGS = set('''param return returns val var throws author version since
deprecated description example file date generated fn type property
method code link see'''.split())


def word_value(word):
    if word.lower() in GREEK:
        return -0.3 if word in {'nu', 'xi'} else 0.05
    if word in SYMBOLS:
        return 0.2 if word in {'frac', 'cdot', 'ell', 'circ'} else -0.35
    if word in OPERATORS:
        return -1.15
    if word in {'right', 'end', 'in'}:
        return -0.55
    if word in LAYOUT:
        return -1.6
    if word in TEXT_CONTROLS or len(word) == 1:
        return -2.6
    if word in {'operator', 'ensure', 'foot'}:
        return -3.4
    return -1.5 if word.startswith('n') or word[0].isupper() else -2.1


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, command = '', ''
    if carry is not None and carry[0] == doc:
        previous, command = carry[1:]
    value, next_command = 0.0, ''
    if previous.endswith('\\'):
        if token == 'n':
            slashes = len(previous) - len(previous.rstrip('\\'))
            value = -2.75 / (1 + 0.6 * (slashes - 1))
        elif token and token[0].isascii() and token[0].isalpha():
            value, next_command = word_value(token), token
        elif token and token[0].isdigit():
            value = -1.5
        elif token[:1] in (')', ']', '}'):
            value = 2.6 if len(token) == 1 else 1.65
            value -= 0.4 if '.' in token else 0.0
        elif token.startswith(('"', "'")):
            value = 2.2 if '/' in token else 0.75
        elif token[:1] in ('$', '|', '%', '#', '&', '{'):
            value = 0.85
        elif token.startswith(('[', '(')):
            value = -0.35
    elif command and token in SUFFIXES:
        strong_prefix = command in {
            'math', 'operator', 'bold', 'foot', 'm', 'h', 'new'
        }
        value = -1.3 if strong_prefix else -0.6
        if command == 'math' and token == 'cal':
            value = -1.7
    elif token in ('\\n', '\\t', '\\x', '\\xc', '\\xe', '\\u'):
        value = -0.6
        if token == '\\n' and previous in {'n', '\\n', '\\t'}:
            value = -0.15
    elif previous.endswith('@') and token in TAGS:
        value = -1.5 if token in {'link', 'see', 'type', 'code'} else -0.9
    return (doc, token, next_command), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4836 - a backslash-escape detector.

The component is switched strongly negative on the word that follows a backslash
in text: the name of an escape or LaTeX command, e.g. the "n" of "\\n" in code
(about -2.7), or "text", "math", "display", "left", "begin", "boxed" (about -2).
Greek letters and common math operators after a backslash (\\alpha, \\frac, \\cdot,
\\rightarrow, \\sqrt, \\right) stay near zero. A backslash followed by punctuation
(\\", \\), \\{, \\]) gives a mild positive value. A single token that is already an
escape such as "\\n" or "\\t" gives a weak negative value. A doubled backslash
(\\\\n in nested escapes) weakens the effect, and a javadoc-style "@" tag word
(@param, @return) gives a weak negative value. Everything else is 0.
"""

READS = ()

GREEK = {"alpha", "beta", "gamma", "delta", "Delta", "epsilon", "eta", "theta", "lambda",
         "mu", "nu", "pi", "rho", "sigma", "Sigma", "tau", "phi", "chi", "psi", "omega",
         "Omega", "zeta", "xi", "iota", "kappa", "upsilon"}
MATH_OPS = {"frac", "cdot", "rightarrow", "sqrt", "right", "times", "approx", "ell",
            "leq", "geq", "infty", "pm", "prime", "sin", "cos"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    word = cur[:1].isalpha()
    if prev.endswith("\\\\"):
        return carry, (-0.9 if word else 0.5)
    if prev.endswith("\\"):
        if cur in GREEK or cur in MATH_OPS:
            return carry, 0.0
        if cur == "n":
            return carry, -2.7
        if word:
            return carry, -2.0
        return carry, 0.9
    if prev in ("@", " @"):
        return carry, (-0.8 if word else 0.0)
    if cur.startswith("\\") and cur[1:2].isalpha():
        return carry, -0.5
    return carry, 0.0

