"""Approximate signals at the start of markup commands and escapes.

The harvested high-impact examples include TeX control words and escaped
characters. Control words usually have negative activations; escaped closing
delimiters can be positive. Common text not in these forms is left at zero.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    begins_escape = previous.endswith("\\")
    embedded_escape = token.startswith("\\")
    spelling = token[1:] if embedded_escape else token
    value = 0.0

    if (begins_escape or embedded_escape) and spelling:
        first = spelling[0]
        if first.isalpha():
            if embedded_escape and not begins_escape:
                value = -0.8 if spelling.startswith("n") else -1.8
            else:
                value = -2.8 if spelling.startswith("n") else -1.8
        elif first == "]":
            value = 2.0
        elif first == "}":
            value = 1.6
        elif first.isdigit():
            value = -1.3
        elif first == "[":
            value = -0.3
    if previous.endswith("@") and token.startswith("param"):
        value = -0.9
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP component 4837 (down_proj): the letter "d".

The component reads the MLP's hidden state, which at layer 0 is almost a pure function
of the current token. It switches on for tokens containing the letter d: Latin d/D, and
its look-alikes in other alphabets (Cyrillic д, Greek δ, Arabic د), plus the katakana
syllables da and de (ダ, デ). Its size depends on where the d sits and how long the token
is:
  - strongest for short tokens: "d", "D", "id", "Id", "ad", "bed", "od", "cd";
  - a d that follows e or n ("-ed", "-nd", as in "need", "and") is weaker;
  - a d at the start of a token is weaker;
  - long tokens, and tokens with a leading space, are weaker;
  - all-caps tokens ("DC", "COVID") are stronger.
The common word " and" is zero. Everything without a d is zero.

This is a hand-set score, not a fit to the model's weights; it reads only the current
token (`prefix.token_strings[-1]`), so it needs no carry.
"""

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip().lower()
    if any(c in "ダデ" for c in raw):  # katakana da, de
        return None, 1.4
    if s == "and":
        return None, 0.0
    hits = [i for i, c in enumerate(s) if c in "dдδد"]
    if not hits:
        return None, 0.0
    i = hits[0]
    if i == 0:
        value = 0.33
    elif s[i - 1] in "en":
        value = 0.56
    else:
        value = 0.9
    if len(s) <= 2:
        value += 0.46
    if len(s) >= 8:
        value -= 0.18
    if raw[:1] == " ":
        value -= 0.17
    if raw.strip().isupper():
        value += 0.22
    return None, max(value, 0.0)

programs.sol:
"""Greek word-internal letters and chat-header roles.

Single Greek letters immediately after Greek text usually get negative
values, amplified most strongly by a preceding epsilon. The alphabet table
calibrates individual letters; the vowel rules describe their local context.
User/assistant role labels after a chat-start marker are positive, smaller
at document starts and slightly larger after tool activity. Tool/think tags
have small fixed signals. Split UTF-8 fragments use the decoded final
character and a six-token recent-Greek heuristic. Other text is mostly zero.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
TOOL_MARKERS = {
    "<tool_call>", "</tool_call>", "<tool_response>", "</tool_response>",
}

# Baseline levels for the Greek alphabet, learned from training text.
LETTERS = {
    'α': -0.55, 'β': -0.46, 'γ': -1.49, 'δ': -1.07,
    'ε': -0.87, 'ζ': -0.81, 'η': 0.14, 'θ': -0.95,
    'ι': -0.60, 'κ': -1.14, 'λ': -1.17, 'μ': -1.61,
    'ν': -0.84, 'ξ': -1.05, 'ο': -0.32, 'π': -0.96,
    'ρ': -1.54, 'σ': -1.06, 'ς': -0.60, 'τ': -0.66,
    'υ': -1.39, 'φ': -1.27, 'χ': -1.25, 'ψ': -0.09,
    'ω': -0.24, 'ά': -0.50, 'έ': -1.81, 'ί': -0.55,
    'ό': -0.54, 'ή': 0.06, 'ύ': -0.92, 'ώ': -0.05,
}
VOWELS_AND_FINAL_SIGMA = set('αεηιουωάέίόήύώς')

# (consonant gain, offset, vowel/final-sigma gain, offset).
LEFT_VOWEL = {
    'epsilon': (2.4, -2.06, 2.7, -0.41),
    'epsilon_start': (1.87, -1.84, 2.21, -0.42),
    'epsilon_split': (2.0, -0.79, 1.59, -0.54),
    'alpha': (1.33, -0.66, 1.25, -0.21),
    'alpha_start': (1.67, -0.02, 1.27, 0.0),
    'omicron_or_tonos_alpha': (1.26, -0.53, 0.77, -0.37),
    'eta_or_omega': (1.26, 0.68, 0.79, 0.06),
}


@lru_cache(maxsize=32768)
def greek(s):
    return any('GREEK' in ud.name(c, '') for c in s)


def left_vowel(token, char):
    if char in ('ε', 'έ', 'Ε', 'Έ'):
        if token in ('ε', 'έ', 'Ε'):
            return 'epsilon'
        return 'epsilon_start' if token.startswith(' ') else 'epsilon_split'
    if char in ('α', 'Α'):
        return 'alpha' if token == 'α' else 'alpha_start'
    if char in ('ο', 'ό', 'ά', 'Ο', 'Ό', 'Ά'):
        return 'omicron_or_tonos_alpha'
    if char in ('η', 'ω', 'ώ', 'Η', 'Ω'):
        return 'eta_or_omega'
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    previous, char, position, recent, tools = '', '', 0, 0, False
    if carry is not None and carry[0] == doc:
        _, previous, char, position, recent, tools = carry
        position += 1
    current_char = token[-1:]
    if '\ufffd' in token:
        current_char = prefix.text_prefixes[-1][-1:]
    value = 0.0
    if previous == '<|im_start|>':
        if token == 'user':
            value = 0.172 if position == 1 else (0.70 if tools else 0.61)
        elif token == 'assistant':
            value = 0.106 if position == 1 else (0.516 if tools else 0.493)
        elif token == 'system':
            value = -0.125
    elif token in ('<tool_call>', '</tool_response>'):
        value = -0.21
    elif token == '</think>':
        value = 0.26
    elif len(token) == 1 and greek(token):
        if greek(char):
            value = LETTERS.get(token, -0.8)
            context = left_vowel(previous, char)
            if context:
                parameters = LEFT_VOWEL[context]
                offset = 2 if token in VOWELS_AND_FINAL_SIGMA else 0
                gain, bias = parameters[offset:offset + 2]
                value = gain * value + bias
        elif token in ('έ', 'ύ', 'ί'):
            value = LETTERS[token]
    elif '\ufffd' in token:
        if token == ' �' and recent:
            value = 0.85
        elif greek(current_char):
            if current_char in ('η', 'Η'):
                value = 0.78
            elif current_char in ('έ', 'Έ'):
                value = -0.9
            elif current_char in ('ό', 'Ό'):
                value = -0.65
            else:
                value = -0.1
    elif token.startswith(' ') and greek(token):
        value = -0.05
    elif greek(token):
        value = -0.12
    recent = 6 if greek(current_char) else max(0, recent - 1)
    tools = tools or token in TOOL_MARKERS
    return (doc, token, current_char, position, recent, tools), value

