"""Greek letters in the component layers.0.mlp.down_proj:4838.

What it does: the component writes a strong negative signal when the model reads a single
Greek letter (a token that is one Greek alphabet character, such as "ρ", "μ", "ν", "σ").
The signal is strongest when the letter continues a Greek word, i.e. the previous token is
also Greek; the long vowels η, ω (and their accented forms) barely move it. A stray
replacement character (�) that follows a Greek letter gets a positive value, and chat role
names after "<|im_start|>" ("user", "assistant") get a mild positive value. Everything else
is predicted as 0.
"""
import unicodedata

READS = ()

LONG_VOWELS = set("ηωήώΩΗ")

def _is_greek_letter(token):
    return len(token) == 1 and token.isalpha() and "GREEK" in unicodedata.name(token, "")

def _has_greek(token):
    return any("GREEK" in unicodedata.name(c, "") for c in token)

def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = tokens[-2] if same_doc else ""
    if _is_greek_letter(cur):
        if cur in LONG_VOWELS:
            value = 0.0
        else:
            value = -1.2 if _has_greek(prev) else -0.6
    elif "�" in cur and _has_greek(prev):
        value = 0.8
    elif cur in ("user", "assistant") and prev == "<|im_start|>":
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

