    value = ROLE_VALUES.get(token)
    if value is not None:
        text = prefix.text_prefixes[-1]
        if text.endswith("<|im_start|>" + token):
            return None, value
    if any("GREEK" in unicodedata.name(ch, "") for ch in token):
