programs.sol:
"""Negative lexical response to statements and declarations.

Statement(s), including code identifiers and split-word completions, is the
strongest trigger. Related speech/assertion words and a few translations are
weaker. Some response persists into 'statement of/on/about/that'. Noun-ending
fragments also respond weakly. Only the current and preceding token are read;
this detects wording, not whether a statement is true.
"""
READS = ()

# A small lexicon of speech words and declaration-related fragments.
GROUPS = (
    (-2.0, 'declaration declarations'),
    (-1.25, 'stated declare declared declares declaring assertions'),
    (-0.8, 'assertion asserted'),
    (-0.65, 'stat stating decl declar clare sentence sentences sentenced '
             'clause clauses claim claims proclaim proclaimed '
             'remark remarks remarked oath affidavit'),
    (-0.43, 'claimed'),
    (-0.25, 'claiming say saying'),
    (-0.2, 'assert asserts asserting'),
    (-0.07, 'said says'),
)
WORDS = {word: level for level, words in GROUPS for word in words.split()}
WORDS.update({  # translations/characters: statement, sentence, declare, say
    '声明': -3.2, '聲明': -3.2, '陈述': -2.7, '陳述': -2.7,
    '宣言': -2.0, '句': -1.2, '言': -0.65, '申': -1.5,
    'заяв': -1.6, 'بيان': -2.4, 'declaración': -1.6,
})


def response(token, previous):
    text, prev_text = token.strip(), previous.strip()
    word, prev = text.lower(), prev_text.lower()
    bare, head = word.lstrip('._($/-'), prev.lstrip('._($/-')
    value = WORDS.get(bare, 0.0)
    if bare in {'statement', 'statements'}:
        value = -6.4 if bare.endswith('s') else -6.0
        if bare == 'statement' and text.startswith('S'):
            value = -7.6 if token.startswith('S') else -6.7
        if word != bare or token.startswith('\t'):
            value += 0.7
        if prev in {'problem', 'prepared'}:
            value += 1.5
    elif 'statement' in word:
        value = -2.5  # e.g. prepareStatement
    elif bare == 'stmt':
        value = -4.0
    elif bare in {'claration', 'clarations'}:
        value = -1.6
    elif word == '句' and prev in {'语', '語'}:
        value = -3.4
    elif word in {'ment', 'ments', 'ement', 'ements', 'atement'}:
        completed = head + word
        if completed in {'statement', 'statements'}:
            value = -6.8 if completed.endswith('s') else -5.7
            if word in {'ment', 'ments'} and previous.startswith(' '):
                value = -7.5
        elif completed == 'restatement':
            value = -4.4
        else:
            value = -2.0 if word == 'atement' else -0.4
            if text.isupper() or word == 'ements':
                value = -0.85
    if head in {'statement', 'statements'}:
        if word == 'of':
            value = -2.8 if head.endswith('s') else -3.4
            if prev_text.startswith('S'):
                value -= 1.2
                if previous.startswith('S') and head == 'statement':
                    value -= 1.0
        else:
            value += {'on': -1.0, 'about': -0.5, 'that': -0.6}.get(word, 0.0)
    elif head in {'declaration', 'declarations'} and word == 'of':
        value = -0.9
    return value


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    return None, response(prefix.token_strings[-1], previous)

programs.haiku:
"""Layer-0 MLP down_proj component 4839: a "statement / claim" word detector.

The component reads the current token and writes a negative value onto the residual
stream when that token names a formal statement, declaration or claim. The size follows
how strongly the word points at a formal statement:
  * "statement" / "stmt" (any word containing them, e.g. " Statement", "_stmt"): about -6;
  * "stated", "declar..." (declare, declared, declaration), "assertion(s)", "affidavit",
    "oath", and 声明 (Chinese "statement"): about -1.5;
  * "claim(s)", "sentence(s)", "clause(s)", and 句 (Chinese "sentence"): about -0.7.
Every other token gives 0, including code words like assertTrue and 语言. It looks only
at the current token, so context changes the value by about +/-1 at most for "statement".
"""

READS = ()

STRONG_PARTS = ("statement", "stmt")
MEDIUM_PARTS = ("stated", "declar", "assertion", "affidavit", "oath", "声明")
WEAK_WORDS = {"claim", "claims", "sentence", "sentences", "clause", "clauses", "句"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if any(part in word for part in STRONG_PARTS):
        value = -6.0
    elif any(part in word for part in MEDIUM_PARTS):
        value = -1.5
    elif word in WEAK_WORDS:
        value = -0.7
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Recognize language about stating or asserting something.

The clearest signal is the noun 'statement'; related assertion words and
some English/French -ment endings give a smaller negative contribution.
"""
READS = ()

STATEMENT_WORDS = {"statement", "statements"}
ASSERTION_WORDS = {
    "claim", "claims", "claimed", "claiming",
    "say", "says", "said", "stated", "state",
    "declare", "declared", "declaration", "proclaim",
    "remark", "remarks", "sentence", "oath",
    "言", "断", "公告",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    if token in STATEMENT_WORDS:
        return None, -5.9
    if token.endswith(("ement", "ements", "ment", "ments")):
        return None, -1.0
    if token in ASSERTION_WORDS:
        return None, -0.8
    return None, 0.0

"""A tiny lexical baseline: give small offsets by the current token's script and length.

The component has almost no aggregate effect, and its larger activations are scattered
across unrelated text. These broad token-shape averages capture only a faint bias.
"""

READS = ()

import unicodedata

SCRIPT_MEAN = {
    "latin": -0.00125,
    "punct": 0.00123,
    "number": -0.00063,
    "empty": 0.00014,
    "han": 0.00414,
    "cyrillic": -0.00121,
    "letter": -0.00318,
    "kana": -0.00570,
}

LENGTH_MEAN = (
    -0.01524, 0.00172, -0.00066, -0.00145, -0.00239,
    -0.00007, -0.00122, -0.00090, -0.00152,
)


def script_of(text):
    for char in text:
        if char.isspace():
            continue
        name = unicodedata.name(char, "")
        category = unicodedata.category(char)
        if "CJK" in name or "IDEOGRAPH" in name:
            return "han"
        if "HIRAGANA" in name or "KATAKANA" in name:
            return "kana"
        if category.startswith("L"):
            if "LATIN" in name:
                return "latin"
            if "CYRILLIC" in name:
                return "cyrillic"
            return "letter"
        if category.startswith("N"):
            return "number"
        if category.startswith(("P", "S")):
            return "punct"
        return category
    return "empty"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    length = min(len(token), len(LENGTH_MEAN) - 1)
    script_mean = SCRIPT_MEAN.get(script_of(token), -0.00047)
    return None, float(script_mean + LENGTH_MEAN[length] + 0.00047)

programs.sol:
"""Spelling-based approximation of a mostly negative lexical detector.

It responds most strongly to Cyrillic ы and short syllables ending in ы,
including the Russian pronouns мы, вы, ты. Longer fragments are weaker.
A lone ы is stronger after short or capitalized fragments. English we
and several short Latin y spellings also give negative responses. Common
Russian adjective endings in о give a small positive response. This does
not claim that these spellings all have the same meaning.
"""
from math import exp

READS = ()


def _value(text, previous=''):
    word = text.strip()
    low = word.lower()
    word_initial = text[:1].isspace()
    bare = low.strip('."\'“”‘’(/_-')
    if bare == 'we':
        return -0.76 if text == ' we' else -0.91
    if low == 'ы':
        if word.isupper():
            return -5.5
        stem = previous.strip()
        return min(-2.0, -6.0 + 0.45 * min(len(stem), 8)
                   - float(stem[:1].isupper()))
    if low in ('вы', 'мы', 'ты', 'бы'):
        pronoun_like = word_initial or word[:1].isupper()
        if low == 'вы':
            return -5.15 if pronoun_like else -4.4
        if low == 'мы':
            return -4.35 if pronoun_like else -2.95
        if low == 'ты':
            return -3.75 if pronoun_like else -3.4
        return -2.95 if word_initial else -3.9  # conditional particle бы
    if 'ы' in low:
        if word_initial and len(low) >= 4 and not low.startswith('вы'):
            return 0.0
        if low.startswith('н') and low[1:] in ('ый', 'ые', 'ым', 'ых', 'ыми'):
            return -0.7 if low.endswith('й') else -0.4
        if len(low) == 2 and low.endswith('ы'):
            return -3.15
        if low.startswith('ыв'):  # imperfective verb suffix
            return -2.0 if len(low) <= 3 else -0.9 if len(low) <= 5 else -0.35
        if low.startswith('вы'):
            return -3.1 / max(1, len(low) - 1)
        if len(low) <= 6:
            strength = 3.5 if low.endswith('ы') else 1.4
            return -strength * exp(-0.55 * (len(low) - 2))
    if low == 'я':
        return -0.8 if word_initial or word[:1].isupper() else -0.25
    if low == 'они' and word_initial:
        return -0.85 if word.islower() else -0.4
    if not word_initial and 2 <= len(low) <= 6:
        if low.endswith('ки'):
            return -0.5
        if low.endswith(('ое', 'ого', 'ому')):
            return 0.45
        if low.endswith('ой'):
            return -0.22
    if low == 'ý':
        return -0.4 if word_initial else -1.6
    if low == 'wy':
        return -1.9 if word_initial else -1.2
    if bare == 'py':
        return -0.35 if word.startswith('.') else -0.5 if word_initial else -0.8
    if low in ('ny', 'zy', 'dy', 'vy'):
        return -0.35 if word_initial else -0.6
    if low == 'ly' and (word_initial or word[:1].isupper()):
        return -0.6
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    text = prefix.token_strings[-1]
    return (document, text), float(_value(text, previous))

