"""Approximate recurring English 'we' and Cyrillic ы-word triggers."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word == "we":
        starts_word = token[:1].isspace() or prefix.position == 0
        if not starts_word and prefix.position:
            same_doc = (
                prefix.document_ids[-2] == prefix.document_ids[-1]
            )
            if not same_doc:
                starts_word = True
            else:
                whole = prefix.text_prefixes[-1]
                before = whole[:-len(token)] if whole.endswith(token) else ""
                starts_word = not before or not before[-1].isalnum()
        if starts_word:
            return None, -0.9
    if word.endswith("ы"):
        return None, -4.5
    return None, 0.0

programs.sol:
"""Predict local pulses at the beginnings of conditional and temporal clauses.

'If' and 'when' followed by a subject are the main positive pattern,
especially 'I', 'we', and 'you'. Related conjunctions are weaker; verbs
and participles give smaller, word-class-dependent continuations. The
program also recognizes 'let me/let’s' deliberation and a few negative
contexts: thanking someone, 'considered' after a copula, and how/why
before a personal subject. A document-initial if gets a small pulse
even before a subject. Other positions stay near zero.

Only the two previous tokens are remembered, within the same document.
The numeric strengths are estimates from training activations.
"""
READS = ()

IF_RESPONSE = {
    'I': 4.55, 'i': 1.75, 'we': 4.2, 'you': 3.1,
    'it': 1.6, 'he': 1.6, 'she': 1.4, 'they': 1.35,
    'one': 1.8, 'someone': 2.0, 'anyone': 0.9,
    'a': 0.95, 'an': 1.0, 'the': 0.42,
    'this': 0.8, 'that': 0.6, 'there': 0.75,
}
WHEN_RESPONSE = {
    'I': 3.6, 'i': 1.8, 'we': 3.3, 'you': 2.5,
    'it': 1.85, 'he': 1.45, 'she': 1.35, 'they': 1.3,
    'one': 1.5, 'someone': 1.5, 'anyone': 0.8,
    'a': 0.8, 'an': 0.5, 'the': 0.15,
    'this': 0.25, 'that': 0.2, 'there': 0.8,
}
RELATED_CUES = {
    'unless': 0.6, 'whether': 0.5,
    'until': 0.4, 'once': 0.4, 'whenever': 0.5,
    'before': 0.2, 'after': 0.15, 'since': 0.2,
    'while': 0.18, 'as': 0.12, 'where': 0.2,
    'because': 0.1, 'although': 0.1,
}
POSSESSIVES = {'my', 'your', 'our', 'his', 'her', 'their', 'its'}


# Common objects and predicates in programming conditionals.
CODE_TESTS = {'len', 'isinstance', 'issubclass', 'err', 'self'}
SUBJECTS = {'I', 'i', 'we', 'you', 'he', 'she', 'it', 'they'}
# At the next token, a conditional subject can introduce an action.
ACTIONS = {
    'look': 2.0, 'try': 1.7, 'consider': 1.5, 'think': 1.25,
    'take': 1.15, 'go': 0.95, 'run': 0.85, 'add': 0.85,
    'want': 0.75, 'have': 0.65, 'use': 0.55, 'were': 0.55,
    'are': 0.4, 'was': 0.35, 'had': 0.45, 'is': 0.18,
}
DELIBERATION = {
    'try': 0.97, 'think': 0.35, 'consider': 0.43,
    'look': 0.29, 'check': 0.17, 'see': 0.17,
    'compute': 0.24, 'run': 0.23, 'take': 0.65,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == document
    previous, before = carry[1:] if same_document else ('', '')
    token = prefix.token_strings[-1].strip()
    previous = previous.lstrip('.,:;!?\"\'“‘([{—–')
    word, cue = token.lower(), previous.lower()
    value = 0.0
    if cue == 'if':
        value = IF_RESPONSE.get(token, 0.2 if token.isalpha() else 0.0)
        if len(token) == 1 and token.islower() and token != 'a':
            value = 1.75 if token == 'i' else 0.5
        if word in CODE_TESTS:
            value = 0.8
        elif word == 'not':
            value = -0.5
        elif word == 'let' or word == 'and':
            value = 1.3
        elif not token:
            value = 0.5
        if word in POSSESSIVES:
            value = 0.5
    elif cue == 'when' or cue in RELATED_CUES:
        value = WHEN_RESPONSE.get(token, 0.0)
        if cue == 'when':
            if word in {'compared', 'viewed'}:
                value = 3.7
            elif word in {'trying', 'considering', 'looking', 'faced'}:
                value = 2.3
            elif word in {'using', 'use'}:
                value = 1.6
            elif word.endswith('ed') and word.isalpha():
                value = 1.8
            elif word.endswith('ing') and word.isalpha():
                value = 0.8
            elif len(word) == 1 and word.isalpha() and token not in {'I', 'a'}:
                value = 1.8 if word == 'i' else 0.5
        if word in POSSESSIVES:
            value = 0.2
        value *= RELATED_CUES.get(cue, 1.0)
    if previous[:1].isupper() and value > 0:
        value *= 1.23 if cue == 'if' else (1.14 if cue == 'when' else 1.2)
        if token in {'the', 'a', 'an'} and cue in {'if', 'when'}:
            value += 0.25 if cue == 'if' and token == 'the' else 0.15
    if before.lower() in {'if', 'when'} and previous in SUBJECTS:
        value = ACTIONS.get(word, 0.15 if token.isalpha() else 0.0)
        if word in {'can', 'could', 'should', 'cannot'}:
            value = -0.2
    elif before.lower() == 'let' and cue in {'me', "'s", '’s'}:
        value = DELIBERATION.get(word, 0.0)
    elif cue == 'thank' and word == 'you':
        value = -1.4
    elif word == 'considered' and cue in {'is', 'are', 'was', 'were', 'been'}:
        value = -1.2
    elif word == 'considered' and cue == 'be':
        value = -0.65
    elif cue in {'how', 'why'} and token in SUBJECTS:
        value = -0.7 if word == 'we' else -0.35
    if not same_document and word == 'if':
        value = 0.9 if token[:1].isupper() else 0.43
    return (document, token, previous), value

programs.luna:
"""Predict a modest burst on a clause's first word, especially a pronoun."""

import re

READS = ()

PRONOUNS = {
    "i", "me", "my", "mine", "we", "us", "our", "ours",
    "you", "your", "yours", "he", "him", "his", "she", "her",
    "hers", "it", "its", "they", "them", "their", "theirs",
    "who", "what", "someone", "anyone", "everyone",
}
DETERMINERS = {"a", "an", "the", "this", "that", "these", "those"}
SUBORDINATORS = {"if", "when", "while", "until", "before", "after",
                 "once", "since", "though", "although", "because", "as"}


def _word(text):
    words = re.findall(r"[^\W\d_]+", text.lower(), flags=re.UNICODE)
    return words[-1] if words else ""


def step(carry, prefix, upstream):
    pos = len(prefix) - 1
    current = _word(prefix.token_strings[pos])
    same_document = (
        pos > 0 and prefix.document_ids[pos] == prefix.document_ids[pos - 1]
    )
    previous = _word(prefix.token_strings[pos - 1]) if same_document else ""
    if previous not in SUBORDINATORS:
        return None, 0.0
    if current in PRONOUNS:
        value = 0.9
    elif current in DETERMINERS or current == "there":
        value = 0.48
    elif current:
        value = 0.38
    else:
        value = 0.25
    return None, value

programs.sol:
"""A strong negative response to 'that', modulated by the preceding word.

Knowledge and discovery contexts strengthen it; 'so/such that' and ensuring
reverse its sign. Suppositions are near zero. The at-sign has an independent
positive response. This approximation omits most weaker lexical responses.
"""
import re

READS = ()

# Word families introducing clauses: roots, not arbitrary token identifiers.
CLAUSE_FAMILIES = (
    (1.9, 'ensure'),
    (0.1, 'assume suppose imply hope'),
    (-3.25, 'know understand remember'),
    (-2.35, 'see find learn read hear tell recall explain determine specify '
             'decide compute'),
    (-1.65, 'clear think consider note notice mention reveal observe realize realise '
            'recognize recognise estimate feel'),
    (-1.25, 'say state report show indicate confirm conclude agree believe '
            'check announce discover'),
    (-0.2, 'claim argue'),
)
FAMILIES = [(value, set(roots.split())) for value, roots in CLAUSE_FAMILIES]
# Irregular verbs, whose forms also distinguish established from new knowledge.
PAST_FORMS = (
    (-2.35, {'known', 'understood', 'told', 'heard'}),
    (-3.05, {'knew', 'learned'}),
    (-1.75, {'found', 'saw'}),
    (-1.0, {'said', 'thought', 'shown'}),
)


def clause_response(text):
    text = text.rstrip()
    match = re.search(r'[A-Za-z]+$', text)
    raw = match[0] if match else ''
    word = raw.lower()
    if word in {'so', 'such'}:
        return 0.2 if raw == 'So' else 0.76
    if raw in {'Note', 'Notice'}:
        return -0.55
    if word == 'all':
        return -2.75
    if word in {'you', 'us', 'not'} or text.endswith(("n't", 'n’t')):
        return -1.95
    if word in {'me', 'him', 'her', 'them', 'myself'}:
        return -1.35
    if word == 'given':
        return -2.2
    for value, forms in PAST_FORMS:
        if word in forms:
            return value
    # Ordinary English inflections, allowing a final silent e.
    roots = {word}
    if word.endswith('ies'):
        roots.add(word[:-3] + 'y')
    for suffix in ('s', 'es', 'ed', 'ing'):
        if word.endswith(suffix):
            stem = word[:-len(suffix)]
            roots.update((stem, stem + 'e'))
    for value, family in FAMILIES:
        if roots & family:
            return -2.0 if raw == 'Remember' else value
    if word in {'means', 'meaning', 'requires', 'requirement', 'probability',
                'possibility', 'assumption', 'assertion'}:
        return 0.4
    if word in {'way', 'sense', 'extent', 'case', 'event', 'condition', 'sure'}:
        return 0.1
    if word in {'likely', 'possible', 'important', 'idea', 'proposition'}:
        return -0.2
    if word in {'is', 'was', 'are', 'were'}:
        return -0.4
    if word in {'do', 'does', 'have', 'like', 'than', 'out', 'about', 'from'}:
        return -1.25
    if word in {'and', 'but', 'because', 'then', 'suggest', 'suggests',
                'suggested', 'suggesting'} or text.endswith((',', ';', ')')):
        return -0.55
    return -0.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if word.lower() == 'that':
        if not tail:
            value = -0.025 if word == 'that' else -0.7
        else:
            value = -1.02 if word != 'that' else clause_response(tail)
    elif '@' in word:
        if word == '@':
            value = 1.15
        elif word.startswith('[@'):
            value = 0.5
        elif word.startswith(',@'):
            value = 0.7
        elif word.startswith('{@'):
            value = 0.8
        elif word in {'(@', '/@', "'@", '"@', '("@'}:
            value = 1.0
        else:
            value = 0.35
    return (doc, (tail + token)[-80:]), value

"""Approximate the component's predominantly finite-'be' lexical signal.

Is/was/are/were get large estimates unless the preceding word is a listed
pronoun or grammatical connector. Past tense is generally less suppressed.
Word boundaries and capitalization distinguish verbs from word fragments;
subword pieces are joined to identify the preceding word, resetting by document.
Other languages' copulas and a few identifier predicates also respond. Some
auxiliaries, participles, and contractions get small negative estimates;
unlisted tokens stay near zero. Small, arbitrary lexical residuals are omitted.
"""
import re

READS = ()

# Columns: is, was, are, were. Values are activation estimates.
FORMS = {'is': 0, 'was': 1, 'are': 2, 'were': 3}
BASE = (1.17, 1.23, 0.78, 1.04)
SUBJECTS = {
