    'what': (-0.03, 0.32, -0.12, 0.30),
    'there': (0.11, 0.37, -0.12, 0.20),
    'he': (0.49, 0.76, 0.70, 0.67),
    'she': (0.49, 0.76, 0.70, 0.67),
    'i': (0.70, 0.73, 0.55, 0.70),
    'we': (0.30, 0.75, 0.09, 0.47),
    'you': (0.88, 0.80, 0.16, 0.55),
    'they': (0.80, 0.70, 0.22, 0.54),
    'this': (0.95, 1.06, 0.75, 1.00),
