"""Use repeated tree, wood, paper, and plant cues as a lexical proxy.

Join pieces of a split word and emit a pulse when it first matches a listed
root; selected Chinese plant/wood characters also trigger a pulse. This simple
cue does not disambiguate words using their surrounding sentence.
"""

READS = ()

PLANT_WORDS = (
    "forest", "paper", "plant", "grass", "branch", "leaf", "timber",
    "bamboo", "root", "flower",
)
NATURE_CHARACTERS = set("树林木枝草花叶根森竹檀槭")


def matches(word):
    return (
        word.startswith("wood") or word.endswith("wood")
        or word.startswith("tree") or word.endswith("tree")
        or any(root in word for root in PLANT_WORDS)
    )


def step(carry, prefix, upstream):
    position = prefix.position
    document = prefix.document_ids[position]
    if carry is None or carry[0] != document:
        prior_word = ""
    else:
        prior_word = carry[1]

    piece = prefix.token_strings[position]
    # A leading space starts a new word; otherwise this can finish one.
    starts_word = not prior_word or piece[:1].isspace()
    if starts_word:
        word = piece.strip().lower()
    else:
        word = (prior_word + piece).lower()

    # Keep a bounded fragment so even malformed/long identifiers stay cheap.
    word = word[-48:]
    value = 0.0
    if any(ch in NATURE_CHARACTERS for ch in piece):
        value = 0.65
    elif matches(word) and not matches(prior_word):
        value = 0.65

    # After a boundary, do not keep appending to the previous word.
    if piece and (piece[-1].isspace() or piece[-1] in ",.;:!?()[]{}<>/\\|\"'`-_"):
        next_word = ""
    else:
        next_word = word
    return (document, next_word), float(value)

