    "rate", "rates", "percent", "percentage", "ratio", "proportion",
    "share", "number", "total", "majority", "minority",
}
QUANTITY_WORDS = {
    "many", "few", "fewer", "several", "numerous", "dozen", "dozens",
    "largest", "highest", "lowest", "most", "least", "more", "less",
    "among", "respectively", "decline", "seldom",
}
CONCEPTS = {
    **dict.fromkeys(GROUP_WORDS, 0.63),
    **dict.fromkeys(MEASURE_WORDS, 0.70),
    **dict.fromkeys(QUANTITY_WORDS, 0.43),
    "among": 0.65,
    "largest": 0.60,
    "highest": 0.30,
    "few": 0.35,
    "dozen": 0.25,
    "decline": 0.18,
    "seldom": 0.25,
    "according": 0.70,
}
COUNT_HEADS = MEASURE_WORDS | QUANTITY_WORDS


def _word(text):
    return text.strip().strip(".,;:!?()[]{}\"'“”‘’").lower()


def step(carry, prefix, upstream):
    token = _word(prefix.token_strings[-1])
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ()
    else:
        previous = carry[1]

    value = CONCEPTS.get(token, 0.0)
    if token in {"%", "％", "‰"}:
        value = 0.78
    elif token == "of" and previous and previous[-1] in COUNT_HEADS:
        value = 0.68
    elif token == "to" and previous and previous[-1] == "according":
        value = 0.52
    elif token in {"人", "人群", "人口"}:
        value = 0.58 if token == "人" else 0.75
    elif token in {"多", "不少", "率", "율", "분율"}:
        value = 0.48

    history = (previous + (token,))[-3:]
    # The component is active only on a small fraction of ordinary text, so
    # dilute these lexical clues rather than treating every match as certain.
    return (doc, history), float(0.30 * value)

"""Predict 0.32 at `{"` after `<tool_call>` and a newline; predict zero
elsewhere. This explicit formatting marker had a recurring large response in
the sampled activation windows.
"""

READS = ()


def step(carry, prefix, upstream):
    if len(prefix) < 3 or prefix.token_strings[-1] != '{"':
        return None, 0.0
    if prefix.token_strings[-2] != "\n":
        return None, 0.0
    if prefix.token_strings[-3] != "<tool_call>":
        return None, 0.0
    if not (
        prefix.document_ids[-1]
        == prefix.document_ids[-2]
        == prefix.document_ids[-3]
    ):
        return None, 0.0
    return None, 0.32

programs.sol:
"""Lexical choice detector, with a brief grammatical after-effect.

Choose/chose/choosing are strongest. Pick, select, decide and their nouns
are weaker, as are common translations and partial word stems. Capitalization
and embedded code identifiers alter the strength. The next token can retain
some of a choosing word's response, especially in 'choose to/the' or 'choice
of'. These are surface-form rules; they do not resolve every word's meaning.
"""
import re

READS = ()

# Inflections grouped by the ordinary act they describe.
CHOOSE = {
    'choose': -5.5, 'chose': -4.1, 'chosen': -3.7,
    'choosing': -4.5, 'chooses': -4.5, 'chooser': -2.4,
    'choosers': -2.4,
}
PICK = {
    'pick': -3.1, 'picking': -2.2, 'picked': -2.1,
    'picks': -2.3, 'picker': -1.7, 'pickers': -1.7, 'pickup': -0.9,
}
SELECT = {
    'select': -1.7, 'selected': -0.9, 'selecting': -1.7,
    'selects': -1.6, 'selection': -0.65, 'selections': -0.6,
    'selective': -0.8, 'selectively': -0.7, 'selectable': -0.8,
    'selector': -0.55, 'selectors': -0.5,
}
DECIDE = {
    'decide': -2.35, 'decides': -2.05, 'deciding': -2.0,
    'decided': -1.4, 'decision': -0.9, 'decisions': -0.9,
    'choice': -1.3, 'choices': -1.2,
    'prefer': -0.4, 'elect': -0.45, 'determine': -0.4,
}
WORDS = {**CHOOSE, **PICK, **SELECT, **DECIDE}

# Translations of choose/choice, including frequent tokenizer stems.
TRANSLATIONS = {
    'choisir': -3.5, 'chois': -2.7, 'choix': -1.3,
    'выб': -2.2, 'выбрать': -2.0, 'выбира': -2.3,
    'выбр': -1.6, 'выбор': -1.2,
    'escol': -2.0, 'wäh': -2.0, 'eleg': -0.7,
    '선택': -2.3, 'chọn': -1.9, 'lựa': -1.8,
}
PARTS = {'cho': -0.6, 'ose': -0.5, 'ick': -0.35, 'decid': -0.6}


def lexical_strength(token):
    word = token.strip().strip('._-/()').lower()
    value = WORDS.get(word, TRANSLATIONS.get(word, PARTS.get(word, 0.0)))
    if word == 'choose' and 'Choose' in token:
        value -= 0.7
    if word in PICK and token.strip()[:1].isupper():
        value *= 0.85
    if token.strip() == 'SELECT':
        value = -1.0
    elif word == 'select' and token == 'select':
        value = -1.35
    if '选择' in word or '選擇' in word:
        value = -2.6 if word in ('选择', '選擇') else -2.0
    elif word in ('选', '選'):
        value = -1.1
    elif word in ('挑选', '选取', '選び', 'を選'):
        value = -1.8
    elif word in ('选用', '挑'):
        value = -1.2
    elif word in ('选举', '精选', '筛选', '评选'):
        value = -0.65
    elif word in ('决定', '決定'):
        value = -1.5
    return value, word


# Function words that carry the choice relation forward by one token.
NOUNS = {'choice', 'choices', 'decision', 'decisions', 'selection', 'selections'}


def after_effect(previous, strength, current, token):
    if not strength:
        return 0.0
    if current == 'of' and previous in NOUNS:
        return strength
    if current == 'to':
        if previous in CHOOSE:
            return strength * (0.18 if previous == 'chosen' else 0.28)
        if previous.startswith('decid'):
            return max(-1.3, 0.7 * strength - 0.1)
        return 0.25 * strength
    if current == 'the':
        return (0.45 if previous in SELECT else 0.29) * strength
    if current in ('a', 'an', 'your'):
        return (0.21 if previous in SELECT else 0.16) * strength
    if current == 'on' and previous.startswith('decid'):
        return 0.4 * strength
    if current in ('for', 'between'):
        return max(-0.35, 0.15 * strength)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, strength, tail = '', 0.0, ''
    if carry is not None and carry[0] == doc:
        previous, strength, tail = carry[1:]

    value, word = lexical_strength(token)
    # A word may span tokens; keep just its unfinished spelling, not the row.
    joined = tail + token
    tail = re.split(r'[^\w]+|_', joined)[-1][-32:]
    whole = tail.lower()
    if value == 0.0 and not token[:1].isspace():
        # Completing a choosing word can fire on its final fragment too.
        if whole in CHOOSE:
            value = CHOOSE[whole]
            if token.isupper():
                value *= 0.75
            word = whole
        elif whole.endswith('choos'):
            value, word = -1.7, 'choos'
        elif whole in PICK and len(token) > 1:
            value, word = 0.7 * PICK[whole], whole
        elif whole in DECIDE and len(token) > 1:
            value, word = 0.8 * DECIDE[whole], whole
        elif whole in SELECT and len(token) <= 4:
            value, word = 0.8 * SELECT[whole], whole
    # French "quelque chose" means "something", not an act of choosing.
    if word == 'chose' and previous == 'quelque':
        value = -0.4
    base = value
    value += after_effect(previous, strength, word, token)
    return (doc, word, base, tail), float(value)

