programs.sol:
"""Approximate a document-boundary and pause signal from token shapes.

End-of-text is strongly positive; ellipses ending a line are strongly negative.
Spacing, closing punctuation, blank lines and document position adjust the
ellipsis response. Questions, exclamations and separators ending a line have
smaller negative responses. Chat/tool opening markers get fixed small offsets.
Only document position and the previous token are remembered. Ordinary lexical
variation is deliberately left unmodeled, with zero predicted for other text.
"""
import math
import re

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    position = 0 if reset else carry[1] + 1
    previous = '' if reset else carry[2]
    carry = (doc, position, text)
    if text == '<|endoftext|>':
        return carry, 0.72 if reset else (1.39 if '\n' in previous else 1.49)
    if text == '<tool_response>':
        return carry, -0.32
    if text == '<|im_start|>':
        return carry, -0.07

    newline = '\n' in text
    blank = text.count('\n') > 1
    spaced = text.startswith(' ')
    runs = re.findall(r'\.{2,}|…+', text)
    value = 0.0
    if runs and not ('/' in text and len(max(runs, key=len)) == 2):
        run = max(runs, key=len)
        count = len(run)
        unicode_ellipsis = '…' in run
        tail = text.split(run, 1)[1].strip()
        quoted = any(c in tail for c in '"\'”’')
        if newline:
            if unicode_ellipsis:
                value = -1.70 + 0.20 * blank + 0.30 * spaced + 0.25 * quoted
            else:
                # The keys are lengths of a dot run, not token identities.
                strength = {2: 1.23, 3: 2.65, 4: 2.38}.get(
                    count, 1.65 if count < 8 else 0.40
                )
                value = -strength + (0.20 if count == 2 else 0.45) * blank
                value += 0.65 * spaced if count >= 3 else 0.0
                if quoted:
                    value += 0.85
                elif any(c in tail for c in ')]'):
                    value += 1.50
                value = min(0.0, value)
        elif quoted or '\\' in tail:
            value = -1.10 if '"' in tail or '\\' in tail else -0.65
        elif spaced and (count == 3 or unicode_ellipsis):
            value = 0.12 if unicode_ellipsis else 0.22
        elif count >= 4:
            value = -0.15
        elif '\n' in previous or not any(c.isalnum() for c in previous):
            value = 0.07
        else:
            value = -0.18 if unicode_ellipsis else (-0.21 if count == 2 else -0.32)
    elif newline and not any(c.isalnum() for c in text):
        exclamations = text.count('!') + text.count('！')
        if exclamations:
            value = -0.43 - 0.18 * min(2, exclamations - 1)
            value += 0.10 * blank
        elif '?' in text or '？' in text:
            value = -0.25 + 0.10 * blank
        elif re.fullmatch(r'\s*-+\s*', text):
            value = -0.12 - 0.17 * math.log(min(6, text.count('-')))
        elif text.startswith(' .'):
            value = -0.31
        elif '~' in text:
            value = -0.37

    if newline and value < 0.0:
        value *= 1.0 - 0.12 * math.log(max(4, position) / 128)
    return carry, float(value)

