"""Candidate v3: end-of-text, emphatic punctuation at line end, and ellipses."""
READS = ()
import re

# An ellipsis (three dots or the single character) that ends a line, optionally after a
# closing quote, bracket or semicolon, e.g. "...\n", " ...\n\n", '..."\n', '...");\n'.
LINE_END_ELLIPSIS = re.compile(r"^ ?(\.{2,}|…)[\"'”)\]\;,]*\n")
# Exclamation or question marks at the end of a line, e.g. "!\n", "?\n\n", "！\n".
LINE_END_MARK = re.compile(r"^ ?[!?！？]+\n")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    pos = prefix.position
    if tok == "<|endoftext|>":
        v = 1.47
    elif LINE_END_ELLIPSIS.search(tok):
        # Strongest near the start of a row, weaker later on.
        v = -2.8 if pos < 32 else -1.9
    elif LINE_END_MARK.search(tok):
        v = -0.4 if "!" in tok or "！" in tok else -0.25
    elif tok == " ...":
        v = 0.25
    elif tok in ("...", "…"):
        v = -0.25
    else:
        v = 0.0
    return carry, float(v)

