programs.sol:
"""A lexical showing/visibility detector, not an image or semantic parser.

Show, manifest, and display words fire even in titles and code. Chinese
characters for manifestation are particularly strong. We also approximate
the smaller response to 'of' after collection nouns and to dialogue tags.
Other tokens are neutral; previous-word memory resets at document boundaries.
"""
import re

READS = ()

SHOW = {'show': 1.38, 'shows': 1.21, 'showing': 1.35,
        'showed': 1.17, 'shown': 0.98}
# 'ifest' is a tokenization fragment of 'manifest'.
MANIFEST = {'manifest': 2.7, 'manifests': 2.1, 'manifested': 1.97,
            'manifesting': 2.0, 'manifestation': 1.5,
            'manifestations': 1.25, 'manifesto': 1.9, 'ifest': 2.2}
DISPLAY = {'display': 0.88, 'displays': 0.93,
           'displayed': 0.74, 'displaying': 0.84}
COLLECTIONS = {
    'list', 'variety', 'series', 'set', 'range', 'group', 'pair',
    'collection', 'array', 'bunch', 'sequence', 'sort',
}
TAGS = {'<|im_start|>': 0.16, '<think>': -0.35, '<tool_call>': -0.12}


def strength(token, previous):
    bare = token.strip().lstrip('._-/')
    word = bare.lower()
    if token in TAGS:
        return TAGS[token]
    if word in SHOW:
        return SHOW[word] + (0.16 if word == 'show' and token[0] != ' ' else 0)
    if word in MANIFEST:
        return MANIFEST[word]
    if word in DISPLAY:
        return DISPLAY[word] + (0.2 if word == 'display' and token[0] != ' ' else 0)
    if word in {'explicit', 'explicitly', 'conspicuous', 'blatant', 'visibly'}:
        return 0.92
    if word in {'evident', 'distinctly', 'expressly', 'markedly',
                'prominently', 'noticeably'}:
        return 0.72
    if word in {'visible', 'visibility', 'obvious', 'overt', 'prominent',
                'noticeable', 'pronounced', 'showcase', 'showcases'}:
        return 0.5
    if word in {'apparent', 'obviously', 'evidently', 'exhibit',
                'exhibits', 'exhibited', 'exhibiting', 'exhibition'}:
        return 0.35
    if re.match(r'^(?:show|display)[A-Z]', bare):
        return 0.9  # UI names such as showDialog and displayName
    if word in {'isvisible', 'setvisible', 'setvisibility', 'stringify'}:
        return 1.05
    if word in {'显', '顯'}:  # manifest, show, conspicuous
        if previous.endswith(('浅', '淺')):
            return 1.85  # completing 'easy to understand'
        if previous.endswith('突'):
            return 2.5  # completing 'make conspicuous'
        return 4.9 if word == '显' else 4.4
    if word in {'显得', '彰显', '彰顯', '显现'}:
        return 2.3
    if word in {'显示', '顯示', '显示出', '显著', '顯著', '明显', '明顯'}:
        return 1.8
    if word in {'明显的', '明顯的', '凸显', '突显'}:
        return 1.45
    if word in {'现', '現', '秀', '耀', '昭', '表现', '展现', '体现'}:
        return 0.85
    if word in {'示', '露', '展', '展示', '呈现'}:
        return 0.6
    if word in {'显然', '明明', '明らか'} or word.endswith('显示'):
        return 1.0
    if word in {'показ', 'mostr', 'mostrar', 'mostra', 'zeigt', 'zeigen', '見え'}:
        return 0.65  # Russian, Romance, German, and Japanese showing words
    if word == 'of':
        if previous == 'couple':
            return 0.5
        if previous in COLLECTIONS:
            return 0.24
        if previous in SHOW or previous in DISPLAY:
            return 0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = strength(token, previous)
    return (doc, token.strip().lower()), float(value)

