programs.sol:
"""A punctuation-semicolon detector, not an HTML-entity terminator detector.

The response is largest for a standalone semicolon and smaller when the token
also closes brackets, quotes, calls, or a line. Assignment/bracing context and
being farther into the document reduce the standalone response. Fullwidth and
Arabic semicolons are included; other tokens contribute zero.
"""
import re

READS = ()
ENTITY_END = re.compile(
    r'&(?:#[xX][0-9a-fA-F]+|#\d+|[A-Za-z][A-Za-z0-9]{1,31})$'
)
CODE = re.compile(r'[{}]|(?<![<>=!])=(?!=)')


def response(token, tail, position):
    if '；' in token or '؛' in token:
        return 1.5 if '\n' in token else 3.05
    if ';' not in token:
        return 0.0
    before, after = token.split(';', 1)
    if ENTITY_END.search(tail + before):
        return 0.0
    closing = before.strip()
    newline = '\n' in after
    code = bool(CODE.search(tail))
    distance = min(position, 100) / 100
    if not closing:
        same_line = 3.95 - 0.55 * distance - 0.75 * code
        line_end = 1.22 - 0.21 * distance - 0.12 * code
        if tail and tail[-1].isdigit():
            same_line -= 0.2
        if after.startswith('\\'):
            same_line -= 0.7
        elif after.startswith(';'):
            same_line -= 0.9
        elif after.startswith((')', '/', '}')):
            same_line = 1.3
        elif after.startswith(('"', "'")):
            same_line -= 1.0
    elif ')' in closing:
        if '(' in closing:
            same_line, line_end = (
                (0.88, -0.1) if closing.count(')') > 1 else (1.65, 0.35)
            )
        elif '"' in closing or "'" in closing:
            same_line, line_end = (
                (1.18, 0.14) if '"' in closing else (1.48, 0.25)
            )
        elif closing.count(')') > 1:
            same_line, line_end = 1.2, 0.19
        elif ']' in closing or '}' in closing:
            same_line, line_end = 1.55, 0.3
        else:
            same_line, line_end = 2.95 - 0.32 * distance - 0.65 * code, 0.35
        if before.startswith(' '):
            same_line -= 0.35
    elif ']' in closing:
        same_line, line_end = 2.5, 0.76
    elif '}' in closing:
        same_line, line_end = 2.7, 1.05
        if before.startswith(' '):
            same_line, line_end = 1.8, 0.8
    elif any(c in closing for c in "'\"`"):
        same_line, line_end = 2.2, 0.79
    else:
        same_line, line_end = 3.0, 1.15
    value = line_end if newline else same_line
    if after.count('\n') > 1:
        value -= 0.4 if closing in ('}', "'", '"') else 0.25
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, position = '', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    value = response(token, tail, position)
    return (document, (tail + token)[-220:], position + 1), value
